function getBaseUrl() {
    var tag = new RegExp('"application_uris"(.*)');
    var uri = vcap_app.match(tag);
    if (uri) {
        var tag1 = new RegExp('"(.*)');
        uri = uri[1].match(tag1);
        let application_uris = "";
        for (let index = 0; index < uri[1].length; index++) {
            if (uri[1][index] != '"') {
                application_uris = application_uris + uri[1][index];
            }
            else {
                index = uri[1].length;
            }
        }
        return application_uris;
    }
}

function runWorker(flag, data) {
    return new Promise((resolve, reject) => {
        const worker = new Worker(path.resolve(__dirname, '../Workers/worker')); // Path to your worker script
        worker.on('message', (result) => {
            resolve(result);
        });
        worker.on('error', reject);
        worker.on('exit', (code) => {
            if (code !== 0) reject(new Error(`Worker stopped with exit code ${code}`));
        });
        worker.postMessage({
            action: flag,
            payload: {
                data: data
            }
        }); // Send flag as  message to the worker
    });
}
function extractFromXpr(xpr, result = {}) {
    for (let i = 0; i < xpr.length; i++) {
        if (
            xpr[i]?.ref &&
            xpr[i + 1] === '=' &&
            xpr[i + 2]?.val !== undefined
        ) {
            result[xpr[i].ref[0]] = xpr[i + 2].val;
        }

        // recurse if nested xpr found
        if (xpr[i]?.xpr) {
            extractFromXpr(xpr[i].xpr, result);
        }
    }
    return result;
}


