            //  vFactLocDesc = '';
            let vSelFields,
                vSelFieldsZero,
                vInnerJoin,
                vGroupFields,
                vGroupFieldsZero,
                vOrderBy;
            let vSelFieldsDmd,
                vGroupFieldsDmd,
                vOrderByDmd;
            let columnname = "WEEK";
            let liCompQty,
                liCompQtyZero,
                liDemandQty,

                liBOM,
                liNodeDesc;
            //    vRefProdDesc;
