    // Maintain partial configurations for new product
    srv.on("getSecondaryChar", async (req) => {
        let liresults = [];
        let lsresults = {};
        let vCount = 1;
        let vFlag = '';
        let vCharFlag = '';
        let li_varcharps = [];
        if (req.data.FLAG === 'D' && req.data.PRODUCT_ID !== '') {//For Download Template
            let oProducts = [],
                noDataProd = [],
                sProducts = '';
            if (req.data.PRODUCT_ID.startsWith('[') && req.data.PRODUCT_ID.endsWith(']')) {
                oProducts = JSON.parse(req.data.PRODUCT_ID);
            } else {
                oProducts.push(req.data.PRODUCT_ID);
            }
            sProducts = oProducts.map(id => `'${id}'`).join(', ');
            li_varcharps = await cds.run(
                `SELECT *
            FROM "V_GETVARCHARPS"
            WHERE "PRODUCT_ID"  IN (${sProducts})`
            );


            for (var p = 0; p < oProducts.length; p++) {

                var prodExists = li_varcharps.filter(el => el.PRODUCT_ID === oProducts[p]);

                if (prodExists.length == 0) {
                    noDataProd.push(oProducts[p]);
                }
            }
            let newProducts = '';
            newProducts = noDataProd.map(id => `'${id}'`).join(', ');

            let li_locprodclass;
            li_locprodclass = await cds.run(
                `SELECT DISTINCT "PRODUCT_ID",
                                "CHAR_NUM",
                                "CHAR_NAME",
                                "CHAR_DESC"
                FROM "V_PRODCLSCHARVAL"
                WHERE "PRODUCT_ID" IN (${newProducts}) 
                    ORDER BY PRODUCT_ID,
                             CHAR_NUM`
            );

            for (let iPrd = 0; iPrd < noDataProd.length; iPrd++) {

                vCount = 1;
                let lstempData = li_locprodclass.filter(el => el.PRODUCT_ID === noDataProd[iPrd]);

                for (let i = 0; i < lstempData.length; i++) {
                    vCharFlag = '';
                    lsresults.PRODUCT_ID = lstempData[i].PRODUCT_ID;
                    // lsresults.LOCATION_ID = lstempData[i].LOCATION_ID;
                    lsresults.CHAR_NUM = lstempData[i].CHAR_NUM;
                    lsresults.CHAR_TYPE = 'S';
                    lsresults.CHAR_NAME = lstempData[i].CHAR_NAME;
                    lsresults.CHAR_DESC = lstempData[i].CHAR_DESC;


                    lsresults.SEQUENCE = vCount;
                    liresults.push(GenF.parse(lsresults));
                    vCount = vCount + 1;
                    lsresults = {};

                }

            }


            li_varcharps = li_varcharps.concat(liresults);

            // let lsclassData = await cds.run(`SELECT * FROM V_CLASSCHARVAL`);

            // // Join arrays based on 'id', and set age to '' if no match is found
            //     let combinedArray = li_varcharps.map(item1 => {
            //         let matchingItem = lsclassData.find(item2 => item2.CHAR_NUM === item1.CHAR_NUM);
            //         if (matchingItem) {
            //         return { ...item1, CHAR_NAME: matchingItem.CHAR_NAME, CHAR_DESC:  matchingItem.CHAR_DESC}; // Merge with cbar name from lsclassData
            //         }
            //         return { ...item1, CHAR_NAME: '' , CHAR_DESC: ''}; // If no match, set age to ''
            //     });

            return li_varcharps;
        }


        if (req.data.PRODUCT_ID !== '') {
            li_varcharps = await cds.run(
                `SELECT *
            FROM "V_GETVARCHARPS"
            WHERE "PRODUCT_ID" = '` +
                req.data.PRODUCT_ID +
                `'`
            );
        }
        else {
            li_varcharps = await cds.run(
                `SELECT *
                FROM "V_GETVARCHARPS"`
            );
        }

        if (req.data.FLAG === 'G' && li_varcharps.length > 0) {
            return li_varcharps;
        }
        else if (req.data.FLAG === 'R' || li_varcharps.length === 0) {
            let li_locprodclass;
            if (req.data.PRODUCT_ID !== '') {
                li_locprodclass = await cds.run(
                    `SELECT DISTINCT "PRODUCT_ID",
                                "CHAR_NUM"
                FROM "V_PRODCLSCHARVAL"
                WHERE "PRODUCT_ID" = '` +
                    req.data.PRODUCT_ID +
                    `' ORDER BY PRODUCT_ID,
                CHAR_NUM`
                );
            }
            else {
                li_locprodclass = await cds.run(
                    `SELECT DISTINCT "PRODUCT_ID",
                                    "CHAR_NUM"
                    FROM "V_PRODCLSCHARVAL"
                    ORDER BY PRODUCT_ID,
                    CHAR_NUM`
                );
            }
            const liProd = await cds.run(`SELECT * FROM CP_PRODUCT`);
            vCount = 1;
            for (let iPrd = 0; iPrd < liProd.length; iPrd++) {
                let liMaxProdSeq = await cds.run(`SELECT max("SEQUENCE") as MAXSEQ,
                                                "PRODUCT_ID"
                                        FROM "CP_VARCHAR_PS"
                                        WHERE CHAR_TYPE = 'S'
                                        AND PRODUCT_ID = '`+ liProd[iPrd].PRODUCT_ID + `'
                                        GROUP BY PRODUCT_ID`);
                if (liMaxProdSeq.length > 0) {
                    vCount = liMaxProdSeq[0].MAXSEQ;
                }
                else {
                    vCount = 1;
                }
                for (let i = 0; i < li_locprodclass.length; i++) {
                    if (liProd[iPrd].PRODUCT_ID === li_locprodclass[i].PRODUCT_ID) {
                        vCharFlag = '';
                        lsresults.PRODUCT_ID = li_locprodclass[i].PRODUCT_ID;
                        // lsresults.LOCATION_ID = li_locprodclass[i].LOCATION_ID;
                        lsresults.CHAR_NUM = li_locprodclass[i].CHAR_NUM;
                        lsresults.CHAR_TYPE = 'S';
                        if (li_varcharps.length > 0) {
                            for (let j = 0; j < li_varcharps.length; j++) {
                                if (li_varcharps[j].CHAR_NUM === lsresults.CHAR_NUM &&
                                    li_varcharps[j].PRODUCT_ID === lsresults.PRODUCT_ID) {
                                    vCharFlag = 'X';
                                    break;
                                }
                            }
                            if (vCharFlag === '') {
                                lsresults.SEQUENCE = vCount;
                                liresults.push(lsresults);
                                vCount = vCount + 1;
                            }
                        }
                        else {
                            lsresults.SEQUENCE = vCount;
                            liresults.push(GenF.parse(lsresults));
                            vCount = vCount + 1;
                        }
                        lsresults = {};
                    }
                }
                if (liresults.length > 0) {
                    try {
                        await cds.run(INSERT.into("CP_VARCHAR_PS").entries(liresults));
                        vFlag = 'X';

                    } catch (e) {
                        vFlag = '';
                    }
                    liresults = [];
                    lsresults = {};
                    vCount = 1;
                    vCharFlag = '';
                }
            }
            // if (vFlag === 'X') {
            li_varcharps = await cds.run(
                `SELECT *
                FROM "V_GETVARCHARPS"
                WHERE "PRODUCT_ID" = '` +
                req.data.PRODUCT_ID +
                `'`
            );
            return li_varcharps;
            // }
        }
        // Remove Primary char from Unique char
        else if (req.data.FLAG === 'U') {
            vFlag = '';
            let vId;
            const li_locprodunique = await cds.run(
                `SELECT *
                FROM "CP_UNIQUE_ID_HEADER"
                WHERE "PRODUCT_ID" = '` +
                req.data.PRODUCT_ID +
                `' AND "UID_TYPE" = 'P'`
            );
            // lsresults.LOCATION_ID = req.data.LOCATION_ID;
            lsresults.PRODUCT_ID = req.data.PRODUCT_ID;
            lsresults.UID_TYPE = 'P';
            if (li_locprodunique.length > 0) {
                try {
                    await cds.delete("CP_UNIQUE_ID_HEADER", lsresults);
                    vFlag = 'X';
                } catch (e) {
                    //DONOTHING
                }
            }
            //Remove from CP_SALES_HM based on Config. and Partial Products
            const liAllProducts = await cds.run(
                `SELECT DISTINCT PRODUCT_ID FROM "CP_PARTIALPROD_INTRO"
              WHERE "REF_PRODID" = '${req.data.PRODUCT_ID}'`
            );
            if (liAllProducts.length > 0) {
                for (var l = 0; l < liAllProducts.length; l++) {
                    try {
                        await UPDATE`CP_SALES_HM`
                            .with({
                                PRIMARY_ID: 0
                            })
                            .where(`PRODUCT_ID = '${liAllProducts[l].PRODUCT_ID}'`);
                        // await cds.run(`DELETE FROM "CP_SALES_HM" WHERE "PRODUCT_ID"='${liAllProducts[l].PRODUCT_ID}'`)
                    } catch (e) {
                        //DONOTHING
                    }
                }
            }
            if (vFlag === 'X') {
                for (let i = 0; i < li_locprodunique.length; i++) {
                    vId = parseInt(li_locprodunique[i].UNIQUE_ID);
                    try {
                        await cds.run(
                            `DELETE FROM "CP_UNIQUE_ID_ITEM" WHERE "PRODUCT_ID" = '` + li_locprodunique[i].PRODUCT_ID + `'
                                                              AND "UNIQUE_ID" = `+ vId + ``
                        );
                        vFlag = 'S';
                    }
                    catch (e) {

                    }
                }
            }
            if (vFlag === 'S') {
                lsresults.PRODUCT_ID = req.data.PRODUCT_ID;
                // lsresults.LOCATION_ID = req.data.LOCATION_ID;
                lsresults.CHAR_NUM = 'SUCCESS';
                lsresults.CHAR_TYPE = 'S';
                lsresults.SEQUENCE = vCount;
                li_varcharps.push(GenF.parse(lsresults));
                lsresults = {};
                return li_varcharps;
            }
            else {
                return li_varcharps;
            }
        }


    });

    srv.on("getCharGroupWeightage", async (req) => {


        let product = req.data.PRODUCT_ID;
        let li_varcharps = [],
            li_charMaster = [];
        let finalArray = [];
        let seq = 0;
        let result = [];


        li_varcharps = await cds.run(
            `SELECT *
            FROM "V_CHARGROUPWEIGHTAGE"
            WHERE "PRODUCT_ID" = '` +
            req.data.PRODUCT_ID +
            `'`
        );

        li_charMaster = await cds.run(
            `SELECT DISTINCT A."PRODUCT_ID",
                                A."CLASS_NUM",
                                B.CHAR_NUM, 
                                B.CHAR_NAME, 
                                B.CHAR_DESC 
                        FROM "CP_PRODUCT_CLASS" AS A
                        LEFT OUTER JOIN  CP_CHARACTERISTICS AS B
                            ON A.CLASS_NUM = B.CLASS_NUM 
                        WHERE A."PRODUCT_ID" = '${req.data.PRODUCT_ID}' 
                    ORDER BY A."PRODUCT_ID" ASC`
        );

        const keys = ['CHAR_NUM'];

        if (li_charMaster.length > 0) {
            li_charMaster = GenF.removeDuplicate(li_charMaster, keys);
        }

        if (li_varcharps.length > 0) {
            li_varcharps.sort((a, b) => parseInt(a.SEQUENCE) - parseInt(b.SEQUENCE));
            seq = li_varcharps.length - 1;
            // to get the new char num from master data.
            result = li_charMaster.filter(obj => !li_varcharps.some(obj1 => obj1.CHAR_NUM === obj.CHAR_NUM));

        } else {
            result = li_charMaster;
        }

        if (result.length > 0) {

            for (let i = 0; i < result.length; i++) {
                seq = seq + 1;
                let tempObj = {
                    PRODUCT_ID: result[i].PRODUCT_ID,
                    CHAR_NUM: result[i].CHAR_NUM,
                    CHAR_NAME: result[i].CHAR_NAME,
                    CHAR_DESC: result[i].CHAR_DESC,
                    CHAR_TYPE: 'S',
                    SEQUENCE: seq,
                    GROUP_NAME: null,
                    WEIGHTAGE: null,
                    CHANGED_BY: '',
                    CHANGED_DATE: '',
                    CHANGED_TIME: ''
                    // CHANGED_BY: li_varcharps[0].CHANGED_BY == null ? '' : li_varcharps[0].CHANGED_BY,
                    // CHANGED_BY: li_varcharps[0].CHANGED_DATE == null ? '' : li_varcharps[0].CHANGED_DATE,
                    // CHANGED_BY: li_varcharps[0].CHANGED_TIME == null ? '' : li_varcharps[0].CHANGED_TIME
                };
                if (li_varcharps.length > 0) {
                    tempObj.CHANGED_BY = li_varcharps[0].CHANGED_BY;
                    tempObj.CHANGED_DATE = li_varcharps[0].CHANGED_DATE;
                    tempObj.CHANGED_TIME = li_varcharps[0].CHANGED_TIME;
                }


                li_varcharps.push(tempObj);
            }
        }

        finalArray = JSON.stringify(li_varcharps);

        return finalArray;




    });

