    srv.on("maintainRestrHdr", async (req) => {
        let liresults = [];
        let lsresults = {};
        let liProdChar = {};
        var responseMessage;
        if (req.data.Flag === "C" || req.data.Flag === "E") {
            lsresults.LINE_ID = req.data.LINE_ID;
            lsresults.LOCATION_ID = req.data.LOCATION_ID;
            lsresults.RESTRICTION = req.data.RESTRICTION;
            // if (req.data.Flag === "E") {
            //     try {
            //         await cds.delete("CP_RESTRICT_HEADER", lsresults);
            //     } catch (e) {
            //         //DONOTHING
            //     }
            // }

            lsresults.RTR_DESC = req.data.RTR_DESC;
            lsresults.RTR_QTY = req.data.RTR_QTY;
            lsresults.VALID_FROM = req.data.VALID_FROM;
            lsresults.VALID_TO = req.data.VALID_TO;
            let logData = GenF.getLogInput(req.data.Flag, req, req.data.User);
            lsresults = Object.assign(lsresults, logData)
            liresults.push(lsresults);
            lsresults = {};
            if (liresults.length > 0) {
                try {
                    if (req.data.Flag == "C") {//Create
                        await cds.run(INSERT.into("CP_RESTRICT_HEADER").entries(liresults));
                    }
                    else {//Update
                        await UPDATE`CP_RESTRICT_HEADER`
                            .with({
                                RTR_DESC: liresults[0].RTR_DESC,
                                RTR_QTY: liresults[0].RTR_QTY,
                                VALID_FROM: liresults[0].VALID_FROM,
                                VALID_TO: liresults[0].VALID_TO,
                                CHANGED_DATE: liresults[0].CHANGED_DATE,
                                CHANGED_BY: liresults[0].CHANGED_BY,
                                CHANGED_TIME: liresults[0].CHANGED_TIME
                            })
                            .where(`LOCATION_ID = '${req.data.LOCATION_ID}' AND LINE_ID = '${req.data.LINE_ID}' AND RESTRICTION = '${req.data.RESTRICTION}'`)
                    }
                    responseMessage = " Creation/Updation successful";
                } catch (e) {
                    //DONOTHING
                    responseMessage = " Creation failed";
                    // createResults.push(responseMessage);
                }
            }
        }
        else if (req.data.Flag === "D") {
            lsresults.LINE_ID = req.data.LINE_ID;
            lsresults.LOCATION_ID = req.data.LOCATION_ID;
            lsresults.RESTRICTION = req.data.RESTRICTION;

            //Check if restrictions Likelihood is maintained
            var liLikelihood = await cds.run(
                `SELECT *
               FROM "V_RSTRREQ_PRODCONSD"
                WHERE "LOCATION_ID" = '` + lsresults.LOCATION_ID + `'
                AND "LINE_ID" = '` + lsresults.LINE_ID + `'
                AND "RESTRICTION" = '` + lsresults.RESTRICTION + `'
                `
            );
            if (liLikelihood.length > 0) {
                return responseMessage = `Deletion failed as  Restriction: ${lsresults.RESTRICTION} is maintained in Restriction Likelihood!`
            }
            // if (req.data.Flag === "E" && i === 0) {
            try {
                await cds.delete("CP_RESTRICT_HEADER", lsresults);
                await cds.run(
                    `DELETE FROM "CP_RESTRICT_DETAILS" 
                        WHERE "LOCATION_ID" = '${req.data.LOCATION_ID}'
                        AND "LINE_ID" = '${req.data.LINE_ID}'
                        AND "RESTRICTION" = '${req.data.RESTRICTION}'
                        `);
                responseMessage = "Restriction deleted";
            } catch (e) {
                //DONOTHING
                responseMessage = "Failed to delete Restriction";
            }
            // }
        }
        lsresults = {};
        return responseMessage;
    });
