    srv.on("updateIBPClass", async (req) => {

        let liClassData = {};
        let lsClassData = {};
        let vResponse = 'S';
        liClassData = JSON.parse(req.data.CLASSDATA);
        // var aVarCharData = await cds.run(`SELECT * FROM "CP_VARCHAR_PS" WHERE "PRODUCT_ID"='${liClassData[0].PRODUCT_ID}' ORDER BY "SEQUENCE" `);
        // var obj = {};
        // for (var x = 0; x < aVarCharData.length; x++) {
        //   var key = aVarCharData[x].PRODUCT_ID+"_" + aVarCharData[x].CHAR_NUM;
        //   if (!obj[key]) {
        //   obj[key] = [];
        //       }
        //       obj[key].push(aVarCharData[x]);
        // }
        let DateValue = new Date().toISOString().split('T')[0];
        let timeValue = new Date().toTimeString().split(" ")[0];
        let User = liClassData[0].USER;
        let newCharArray = [];
        for (let i = 0; i < liClassData.length; i++) {
            lsClassData = {};
            lsClassData.CLASS_NUM = liClassData[i].CLASS_NUM;
            if (liClassData[i].IBPCHAR_CHK === 'X') {
                lsClassData.IBPCHAR_CHK = Boolean(true);
                var aVarCharData = await cds.run(`SELECT * FROM "CP_VARCHAR_PS" WHERE "PRODUCT_ID"='${liClassData[i].PRODUCT_ID}' ORDER BY "SEQUENCE" `);
                var obj = {};
                for (var x = 0; x < aVarCharData.length; x++) {
                    var key = aVarCharData[x].PRODUCT_ID + "_" + aVarCharData[x].CHAR_NUM;
                    if (!obj[key]) {
                        obj[key] = [];
                    }
                    obj[key].push(aVarCharData[x]);
                }
                vResponse = await updateCharType(liClassData[i], obj, aVarCharData);

                var aclassCharData = await cds.run(`SELECT * FROM "CP_CHARACTERISTICS" WHERE "CLASS_NUM"='${liClassData[i].CLASS_NUM}' AND "ENTRY_REQ" != 'X' ORDER BY "CHAR_NUM" `);

                for (var c = 0; c < aclassCharData.length; c++) {
                    var CharData = await cds.run(`SELECT * FROM "CP_CHAR_VALUES" WHERE "CHAR_NUM"='${aclassCharData[c].CHAR_NUM}' ORDER BY "CHAR_NUM" `);
                    if (CharData.findIndex(f => f.CHARVAL_NUM == 'ZZZZ') == -1 && CharData.length > 0) {
                        let obj = {
                            CHAR_NUM: CharData[0].CHAR_NUM,
                            CHARVAL_NUM: 'ZZZZ',
                            CHAR_VALUE: 'ZZZZ',
                            CHARVAL_DESC: 'ZZZZ',
                            REF_CHAR_NUM: CharData[0].CHAR_NUM,
                            REF_CHARVAL_NUM: 'ZZZZ',
                            REF_CHAR_VALUE: 'ZZZZ'
                        }
                        newCharArray.push(obj);

                    }
                }
            }
            else {//Check if it exists as Primary
                lsClassData.IBPCHAR_CHK = Boolean(false);
            }
            if (vResponse === 'S') {
                try {
                    await UPDATE`CP_CLASS`
                        .with({
                            IBPCHAR_CHK: lsClassData.IBPCHAR_CHK,
                            CHANGED_BY: User,
                            CHANGED_DATE: DateValue,
                            CHANGED_TIME: timeValue
                        })
                        .where(`CLASS_NUM = '${lsClassData.CLASS_NUM}'`);
                    vResponse = "S";
                }
                catch (e) {
                    vResponse = "E";
                }
            }
            else if (vResponse === "X") {
                return vResponse;
            }
        }
        let newres = '';
        if (newCharArray.length > 0) {
            try {
                await cds.run(UPSERT.into('CP_CHAR_VALUES').entries(newCharArray));

            } catch (e) {
                newres = 'X';
            }
        }
        if (newres == "X") {
            vResponse = "W";
        }
        return vResponse;
    });


