    srv.on("createLineMasterBatch", async req => {
        let lsResults = {};
        let liResults = {};
        let finalResults = [];
        let lMessage = 'Entry exists for Loc/Line/Line Desc: ', vErrFlag = '';
        lsResults = JSON.parse(req.data.PRODATA);
        var logData = GenF.getLogInput(req.data.Flag, req, req.data.User);
        for (var i = 0; i < lsResults.length; i++) {
            let liFactoryLoc = [];
            liFactoryLoc = await cds.run(`
                                            SELECT * 
                                              FROM CP_LINEMASTER 
                                             WHERE LOCATION_ID = '${lsResults[i].LOCATION_ID}'
                                               AND LINE_DESC = '${lsResults[i].LINE_DESC}'
                                               AND LINE_ID = '${lsResults[i].LINE_ID}'`);

            if (liFactoryLoc.length > 0) {
                lMessage = lMessage + lsResults[i].LOCATION_ID.toString() + '/' + lsResults[i].LINE_ID.toString() + '/' + lsResults[i].LINE_DESC.toString() + ' ';
                vErrFlag = 'X'
            }
            else {

                liResults.LOCATION_ID = lsResults[i].LOCATION_ID;
                liResults.LINE_DESC = lsResults[i].LINE_DESC;
                liResults.LINE_ID = lsResults[i].LINE_ID;
                liResults = Object.assign(liResults, logData)
                finalResults.push(liResults)
                liResults = {};
            }
        }
        try {
            if (req.data.Flag == 'C') {
                if (finalResults.length > 0) {
                    await cds.run(INSERT.into("CP_LINEMASTER").entries(finalResults));
                    if (vErrFlag === 'X') {
                        responseMessage1 = lMessage + ', Creating the remaining entries'
                    }
                    else {
                        responseMessage1 = "Created Successfully";
                    }

                }
                else {
                    responseMessage1 = lMessage;
                }
            }
            else {//update
                await UPDATE`CP_LINEMASTER`
                    .with({
                        LINE_DESC: finalResults[0].LINE_DESC,
                        CHANGED_DATE: finalResults[0].CHANGED_DATE,
                        CHANGED_BY: finalResults[0].CHANGED_BY,
                        CHANGED_TIME: finalResults[0].CHANGED_TIME,
                    })
                    .where(`LOCATION_ID = '${finalResults[0].LOCATION_ID}'
                                  AND LINE_ID ='${finalResults[0].LINE_ID}' 
                                  `);
                responseMessage1 = "Updation Successfull";
            }


        } catch (e) {
            responseMessage1 = "Creation Failed";
        }
        return responseMessage1;

    });
