            let Index = CalendarData.findIndex(el => new Date(el.PERIODSTART) <= new Date() && new Date(el.PERIODEND) >= new Date() && el.LEVEL === 'M');
            // let Index = CalendarData.findIndex(el=> new Date(el.PERIODSTART) <= new Date() && new Date(el.PERIODEND) >= new Date() && el.TPLEVEL === 4);
            let weekValue = 0;
