    srv.on('getGlobalPlanningConfig', async (req) => {
        let loResults = {};

        let laPlandParamValues = await cds.run(`SELECT *
        FROM CP_PARAMETER_VALUES
        INNER JOIN CP_LOCATION
        ON CP_LOCATION.LOCATION_ID = CP_PARAMETER_VALUES.LOCATION_ID
        WHERE PARAMETER_ID IN(6,7,8,10,14,19,20,21,22,23,24,25,26)` );


        let versions = await cds.run(`SELECT * from CP_IBPVERSIONSCENARIO`);

        const keys = ['PARAMETER_ID'];

        if (laPlandParamValues.length > 0) {
            laPlandParamValues = GenF.removeDuplicate(laPlandParamValues, keys);
        }

        for (let i = 0; i < laPlandParamValues.length; i++) {


            switch (laPlandParamValues[i].PARAMETER_ID) {
                case 6:
                    loResults.SEEDORDSEQ = laPlandParamValues[i].VALUE;
                    break;
                case 7:
                    loResults.SOPREFIX = laPlandParamValues[i].VALUE;
                    break;
                case 8:
                    loResults.IBPPLANAREA = laPlandParamValues[i].VALUE;
                    break;
                case 10:
                    loResults.IBPPREFIX = laPlandParamValues[i].VALUE;
                    break;
                case 14:
                    if (laPlandParamValues[i].VALUE === 'false') {
                        loResults.IDENTIFY_RULE_VALIDITY = false;
                    } else {
                        loResults.IDENTIFY_RULE_VALIDITY = true;
                    }
                    // loResults.IDENTIFY_RULE_VALIDITY = Boolean(laPlandParamValues[i].VALUE);
                    break;
                case 19:
                    loResults.IDENTIFY_PVS_NODE = laPlandParamValues[i].VALUE;
                    break;
                case 20:
                    let ver = versions.filter(e => e.VERSION === laPlandParamValues[i].VALUE);
                    loResults.IBPVERSION = laPlandParamValues[i].VALUE;
                    loResults.VERSION = laPlandParamValues[i].VALUE;
                    loResults.VERSION_NAME = ver.length > 0 ? ver[0].VERSION_NAME : '';
                    break;
                case 21:
                    let sce = versions.filter(e => e.VERSION === laPlandParamValues[i].VALUE);
                    loResults.IBPSCENARIO = laPlandParamValues[i].VALUE;
                    loResults.SCENARIO = laPlandParamValues[i].VALUE;
                    loResults.SCENARIO_NAME = sce.length > 0 ? sce[0].SCENARIO_NAME : '';
                    break;
                case 22:
                    loResults.WEEKS = laPlandParamValues[i].VALUE;
                    break;
                case 23:
                    loResults.MONTHS = laPlandParamValues[i].VALUE;
                    break;
                case 24:
                    loResults.QUARTER = laPlandParamValues[i].VALUE;
                    break;
                case 25:
                    if (laPlandParamValues[i].VALUE === 'false' || laPlandParamValues[i].VALUE === false) {
                        loResults.INTER_ASSEMBLY = false;
                    } else {
                        loResults.INTER_ASSEMBLY = true;
                    }
                    break;
                case 26:
                    loResults.PIRPLANREQ = laPlandParamValues[i].VALUE;
                    break;
            }
        }

        if (loResults) {
            return (JSON.stringify(loResults));
        }

    });



    srv.on('getProdPredCheck', async (req) => {
        let vFlagPred = '';
        let lsresults = {}, liresults = [];
        const liProdPred = await cds.run(`

        SELECT DISTINCT REF_PRODID as PRODUCT_ID
          FROM "CP_PARTIALPROD_INTRO" 
         INNER JOIN "CP_TS_PREDICTIONS"
            ON "CP_PARTIALPROD_INTRO"."PRODUCT_ID"  = "CP_TS_PREDICTIONS"."PRODUCT_ID"
           AND "CP_PARTIALPROD_INTRO"."LOCATION_ID" = "CP_PARTIALPROD_INTRO"."LOCATION_ID"
           `);

        const liProd = await cds.run(` SELECT * FROM CP_PRODUCT`);

        for (let iPrd = 0; iPrd < liProd.length; iPrd++) {
            vFlagPred = '';
            for (let iPred = 0; iPred < liProdPred.length; iPred++) {
                if (liProd[iPrd].PRODUCT_ID === liProdPred[iPred].PRODUCT_ID) {
                    lsresults.PRODUCT_ID = liProd[iPrd].PRODUCT_ID;
                    lsresults.PROD_DESC = liProd[iPrd].PROD_DESC;
                    lsresults.PREDICTION_CHK = 'X';
                    vFlagPred = 'X';
                    break;
                }
            }
            if (vFlagPred === '') {
                lsresults.PRODUCT_ID = liProd[iPrd].PRODUCT_ID;
                lsresults.PROD_DESC = liProd[iPrd].PROD_DESC;
                lsresults.PREDICTION_CHK = ' ';
            }
            liresults.push(GenF.parse(lsresults));
            lsresult = {};
        }
        return liresults;
    });
    // Service to get weekly component capacity
    srv.on("getCompCapacityWeekly", async (req) => {
        let vDateFrom = req.data.FROMDATE; //"2022-03-04";
        let vDateTo = req.data.TODATE; //"2023-01-03";
        let liCompQtyWeekly = [];
        let lsCompQtyWeekly = {};
        let liDates = [],
            vWeekIndex,
            vCompIndex,
            lsDates = {};
        let columnname = "WEEK";
        let liDistinctComp = [];
        let liCompQty = [];

        liCompQty = await cds.run(
            `
           SELECT * FROM "CP_COMPONENT_AVAIL"
            WHERE "LOCATION_ID" = '${req.data.LOCATION_ID}'                
              AND ( "WEEK_DATE" >= '${vDateFrom}'
              AND   "WEEK_DATE" <= '${vDateTo}') 
         ORDER BY 
                    "LOCATION_ID" ASC, 
                    "COMPONENT" ASC,
                    "WEEK_DATE" ASC`
        );

        liDistinctComp = await cds.run(
            `
           SELECT DISTINCT "LOCATION_ID",
                           "COMPONENT",
                           "COMP_DESC"
             FROM "CP_ASSEMBLY_COMP"
            WHERE "LOCATION_ID" = '${req.data.LOCATION_ID}' 
         ORDER BY 
                "LOCATION_ID" ASC, 
                "COMPONENT" ASC`
        );

        liCriticalComp = await cds.run(
            `
            SELECT DISTINCT "LOCATION_ID",
                             "COMPONENT",
                             "COMP_DESC",
                             "CRITICALKEY"
                    FROM "CP_CRITICAL_COMP"
                    WHERE "LOCATION_ID" = '${req.data.LOCATION_ID}'
                    ORDER BY 
                    "LOCATION_ID" ASC, 
                    "COMPONENT" ASC
            `
        );

        var vDateSeries = vDateFrom;
        let dDate = new Date(vDateSeries);
        let dDay = dDate.getDay();
        if (dDay === 1) {
            lsDates.WEEK_DATE = vDateFrom;
        } else {
            lsDates.WEEK_DATE = GenF.getNextMondayCmp(vDateSeries);
        }

        vDateSeries = lsDates.WEEK_DATE;
        liDates.push(lsDates);
        lsDates = {};
        while (vDateSeries <= vDateTo) {
            vDateSeries = GenF.addDays(vDateSeries, 7);

            lsDates.WEEK_DATE = vDateSeries;
            liDates.push(lsDates);
            lsDates = {};
        }

        for (let j = 0; j < liDistinctComp.length; j++) {
            // Initially set vWeekIndex to j to geneate Week columns
            // vCompIndex is to get Component quantity for all dates
            vWeekIndex = 0; //j
            lsCompQtyWeekly.LOCATION_ID = liDistinctComp[j].LOCATION_ID;
            lsCompQtyWeekly.COMPONENT = liDistinctComp[j].COMPONENT;
            lsCompQtyWeekly.COMP_DESC = liDistinctComp[j].COMP_DESC;
            lsCompQtyWeekly.CRITICALKEY = "";
            for (let i = 0; i < liDates.length; i++) {
                vWeekIndex = vWeekIndex + 1;
                lsCompQtyWeekly[columnname + vWeekIndex] = -1;
                for (vCompIndex = 0; vCompIndex < liCompQty.length; vCompIndex++) {
                    // lsCompQtyWeekly[columnname + vWeekIndex] = 0;
                    if (liCompQty[vCompIndex].LOCATION_ID === lsCompQtyWeekly.LOCATION_ID &&
                        liCompQty[vCompIndex].COMPONENT === lsCompQtyWeekly.COMPONENT &&
                        liCompQty[vCompIndex].WEEK_DATE === liDates[i].WEEK_DATE
                    ) {

                        lsCompQtyWeekly[columnname + vWeekIndex] =
                            liCompQty[vCompIndex].COMPAVAIL_QTY;
                        break;
                    }
                }
            }

            if (liCriticalComp.length > 0) {//To set Critical key
                var findComp = liCriticalComp.findIndex(c => c.LOCATION_ID == lsCompQtyWeekly.LOCATION_ID && c.COMPONENT == lsCompQtyWeekly.COMPONENT);
                if (findComp != -1) {
                    lsCompQtyWeekly.CRITICALKEY = liCriticalComp[findComp].CRITICALKEY;
                }
            }

            liCompQtyWeekly.push(GenF.parse(lsCompQtyWeekly));
            lsCompQtyWeekly = {};
        }

        // liCompWeekly.sort(GenF.dynamicSortMultiple("STRUC_NODE", "COMPONENT", "ITEM_NUM"));
        return liCompQtyWeekly;

    });
