    // Service to get weekly Restrictions capacity
    srv.on("getRestrictionAvailability", async (req) => {
        let vDateFrom = req.data.FROMDATE;
        let vDateTo = req.data.TODATE;
        let liresQtyWeekly = [];
        let lsresQtyWeekly = {};
        let liDates = [],
            vWeekIndex,
            vCompIndex,
            lsDates = {};
        let columnname = "WEEK";
        let liDistinctRes = [];
        let liresQty = [];

        liresQty = await cds.run(
            `
           SELECT * FROM "CP_RESTRICTION_AVAIL"
            WHERE "LOCATION_ID" = '${req.data.LOCATION_ID}'                
              AND ( "WEEK_DATE" >= '${vDateFrom}'
              AND   "WEEK_DATE" <= '${vDateTo}') 
         ORDER BY 
                    "LOCATION_ID" ASC, 
                    "RESTRICTION" ASC,
                    "WEEK_DATE" ASC`
        );

        liDistinctRes = await cds.run(
            `
           SELECT DISTINCT "LOCATION_ID",
                           "RESTRICTION",
                           "RTR_DESC",
                           "LINE_ID"
             FROM "CP_RESTRICT_HEADER"
            WHERE "LOCATION_ID" = '${req.data.LOCATION_ID}' 
                AND "LINE_ID" = '${req.data.LINE_ID}'
         ORDER BY 
                "LOCATION_ID" ASC, 
                "RESTRICTION" ASC`
        );

        var vDateSeries = vDateFrom;
        let dDate = new Date(vDateSeries);
        let dDay = dDate.getDay();
        if (dDay === 1) {
            lsDates.WEEK_DATE = vDateFrom;
        } else {
            lsDates.WEEK_DATE = GenF.getNextMondayCmp(vDateSeries);
        }

        vDateSeries = lsDates.WEEK_DATE;
        liDates.push(lsDates);
        lsDates = {};
        while (vDateSeries <= vDateTo) {
            vDateSeries = GenF.addDays(vDateSeries, 7);

            lsDates.WEEK_DATE = vDateSeries;
            liDates.push(lsDates);
            lsDates = {};
        }

        for (let j = 0; j < liDistinctRes.length; j++) {
            // Initially set vWeekIndex to j to geneate Week columns
            // vCompIndex is to get Component quantity for all dates
            vWeekIndex = 0; //j
            lsresQtyWeekly.LOCATION_ID = liDistinctRes[j].LOCATION_ID;
            lsresQtyWeekly.RESTRICTION = liDistinctRes[j].RESTRICTION;
            lsresQtyWeekly.RTR_DESC = liDistinctRes[j].RTR_DESC;
            lsresQtyWeekly.LINE_ID = liDistinctRes[j].LINE_ID;

            for (let i = 0; i < liDates.length; i++) {
                vWeekIndex = vWeekIndex + 1;
                lsresQtyWeekly[columnname + vWeekIndex] = -1;
                for (vCompIndex = 0; vCompIndex < liresQty.length; vCompIndex++) {
                    // lsresQtyWeekly[columnname + vWeekIndex] = 0;
                    if (liresQty[vCompIndex].LOCATION_ID === lsresQtyWeekly.LOCATION_ID &&
                        liresQty[vCompIndex].RESTRICTION === lsresQtyWeekly.RESTRICTION &&
                        liresQty[vCompIndex].WEEK_DATE === liDates[i].WEEK_DATE
                    ) {

                        lsresQtyWeekly[columnname + vWeekIndex] =
                            liresQty[vCompIndex].RESTRICTIONAVAIL_QTY;
                        break;
                    }
                }
            }
            liresQtyWeekly.push(GenF.parse(lsresQtyWeekly));
            lsresQtyWeekly = {};
        }
        return liresQtyWeekly;

    });
