    //Function used in Line Master to Delete Lines
    srv.on("deleteLine", async (req) => {
        var aLines = JSON.parse(req.data.Lines);
        var bError = false, liLines = [];
        if (aLines.length > 0) {//check if any restrictions are maintained for the lines 
            var sQuery = "";
            aLines.forEach((l, i) => {
                if (i == 0) {
                    sQuery = `SELECT * FROM "CP_RESTRICT_HEADER"
                    WHERE "LOCATION_ID" = '` + l.LOCATION_ID + `'
                    AND "LINE_ID" = '` +
                        l.LINE_ID + `'`;
                }
                else {
                    sQuery = sQuery + `
                    OR "LOCATION_ID" = '` + l.LOCATION_ID + `'
                    AND "LINE_ID" = '` +
                        l.LINE_ID + `'`;
                }
            })
            sQuery = sQuery + " ORDER BY " +
                " LINE_ID " + ' ASC ';
            const liRestrictions = await cds.run(sQuery);
            if (liRestrictions.length > 0) {
                bError = true;
                liRestrictions.forEach(r => {
                    const obj = {
                        LOCATION_ID: r.LOCATION_ID,
                        LINE_ID: r.LINE_ID,
                        RESTRICTION: r.RESTRICTION,
                        RTR_DESC: r.RTR_DESC
                    }
                    liLines.push(obj);
                })
            }
            else {//Delete Directly
                try {
                    for (let i = 0; i < aLines.length; i++) {
                        await cds.run(
                            `DELETE FROM "CP_LINEMASTER" 
                            WHERE "LOCATION_ID" = '${aLines[i].LOCATION_ID}'
                            AND "LINE_ID" = '${aLines[i].LINE_ID}'
                            `);
                    }
                    bError = false;
                }
                catch (ex) {
                    bError = true;
                }
            }
        }
        return {
            'message': JSON.stringify(liLines),
            'error': bError
        }
    })

