                oODChar.CLASS_NAME = aBOMODChar[iBOMODChr].CLASS_NAME;
                oODChar.CLASS_DESC = aBOMODChar[iBOMODChr].CLASS_DESC;
                oODChar.CHAR_NUM = aBOMODChar[iBOMODChr].CHAR_NUM;
                oODChar.CHAR_NAME = aBOMODChar[iBOMODChr].CHAR_NAME;
                oODChar.CHAR_DESC = aBOMODChar[iBOMODChr].CHAR_DESC;
                oODChar.CHARVAL_NUM = aBOMODChar[iBOMODChr].CHARVAL_NUM;
                oODChar.CHAR_VALUE = aBOMODChar[iBOMODChr].CHAR_VALUE;
                oODChar.CHARVAL_DESC = aBOMODChar[iBOMODChr].CHARVAL_DESC;
