    srv.on("uploadUniqueId", async (req) => {
        var aData = [];
        //Get data from table JOB_SAVEDCONFIG_DATA
        var sequence = JSON.parse(req.data.sequence_ID);
        //Getting all the data of all Activities based on sequence_ID 
        var liSequences = await cds.run(
            `SELECT * FROM "JOB_SAVEDCONFIG_DATA"
          WHERE "SEQUENCE_ID" = '` + sequence + `'`
        );
        if (liSequences.length > 0) {
            aData = liSequences[0].CONFIG_DATA.toString();
        }

        var aUniqueData1 = JSON.parse(aData);
        var query = ""; prodQuery = "";
        var uniqueList = [], jsonData = [], aUniqueData = [];
        var aUniqueList = [], newProducts = [];
        const logObj = {
            "Type": "",
            "Description": "",
            "resultData": '',
            "resultCode": ''
        }
        //Validation - Check for Duplicate entries in JSON
        var keys = ['product', 'externalIdentification'];
        var aDistinctData = Catservicefn.removeDuplicatemultiple(aUniqueData1, keys);
        if (aDistinctData.length != aUniqueData1.length) {
            await GenF.jobSchMessage(' ', 'Cannot upload,Duplicate entries exists!', req);
            return;
        }
        //Get all characteristics from CP_CHARACTERISTICS for validating whether single or mutli characteristic
        var aCharacteristics = await cds.run(
            `SELECT * FROM "CP_CHARACTERISTICS"`
        )
        Array.from(aUniqueData1).forEach(el => {
            let numberCheck = /^\d+$/.test(el.product);
            if (numberCheck == true) { //It is Only number with no special characteristics
                el.product = GenF.removeSOleadzeros(el.product);
            }
            //Remove characteristics with blank characteristic or characteristicValue
            el.characteristics = el.characteristics.filter(f => f.characteristic.toString().trim() != '' && f.characteristicValue.toString().trim() != '');
            //Remove duplicates based on characteristic,characteristicValue and MULTI_CHAR from CP_CHARACTERISTICS
            var aTempCharacteristics = [];
            Array.from(el.characteristics).forEach(ch => {
                let icharIndex = aCharacteristics.findIndex(f => f.CHAR_NAME == ch.characteristic);
                if (icharIndex != -1) {
                    if (aCharacteristics[icharIndex].MULTI_CHAR == 'X') {//Multi Characteristic
                        if (aTempCharacteristics.findIndex(t => t.characteristic == ch.characteristic && t.characteristicValue == ch.characteristicValue) == -1) {
                            aTempCharacteristics.push(ch);
                        }
                    }
                    else {//Single characteristic
                        if (aTempCharacteristics.findIndex(t => t.characteristic == ch.characteristic) == -1) {//To remove duplicates
                            aTempCharacteristics.push(ch);
                        }
                    }
                }
                else {
                    aTempCharacteristics.push(ch);
                }
            })
            el.characteristics = aTempCharacteristics;
            // el.characteristics = Catservicefn.removeDuplicate(el.characteristics, "characteristic");
            const obj = {
                PRODUCT_ID: el.product,
                EX_IDENTIFICATION: el.externalIdentification,
                UNIQUE_DESC: el.uniqueIDDescription,
            }
            if (uniqueList.findIndex(u => u.PRODUCT_ID == el.product && u.EX_IDENTIFICATION == el.externalIdentification) == -1) {
                uniqueList.push(obj);
            }
        })

        //first check if product exists in CP_PARTIALPROD_INTRO
        const liProducts = await cds.run(
            `SELECT * FROM "CP_PARTIALPROD_INTRO"`
        )
        //Get all Products from CP_PRODUCT
        const liConfigProducts = await cds.run(
            `SELECT * FROM "CP_PRODUCT"`
        )
        //Remove Leading zeroes from liProducts
        if (liProducts.length > 0) {//For comparison without leading zeroes
            liProducts.forEach(l => {
                let numberCheck = /^\d+$/.test(l.PRODUCT_ID);
                l.modifiedPRODUCT_ID = l.PRODUCT_ID;
                if (numberCheck == true) { //It is Only number with no special characteristics
                    l.modifiedPRODUCT_ID = GenF.removeSOleadzeros(l.PRODUCT_ID);
                    l.PRODUCT_ID = l.modifiedPRODUCT_ID;
                }
            })
        }
        //Remove Leading zeroes from liConfigProducts and store in modifiedPRODUCT_ID
        if (liConfigProducts.length > 0) {//For comparison without leading zeroes
            liConfigProducts.forEach(l => {
                let numberCheck = /^\d+$/.test(l.PRODUCT_ID);
                l.modifiedPRODUCT_ID = l.PRODUCT_ID;
                if (numberCheck == true) { //It is Only number with no special characteristics
                    l.modifiedPRODUCT_ID = GenF.removeSOleadzeros(l.PRODUCT_ID);
                }
            })
        }
        /*Scenario - Replace Partial Products to its Configproduct*/
        if (liProducts.length > 0 && uniqueList.length > 0) {
            uniqueList.forEach(u => {
                let iRec = liProducts.findIndex(f => f.PRODUCT_ID == u.PRODUCT_ID);
                if (iRec != -1) {
                    let cConfigChk = liProducts[iRec].CONFIGPROD_CHK;
                    if (cConfigChk != "X") {//Current Product is not ConfigProduct
                        let numberCheck = /^\d+$/.test(liProducts[iRec].REF_PRODID);
                        if (numberCheck == true) { //It is Only number with no special characteristics
                            u.PRODUCT_ID = GenF.removeSOleadzeros(liProducts[iRec].REF_PRODID)
                        }
                        else {
                            u.PRODUCT_ID = liProducts[iRec].REF_PRODID;
                        }
                    }
                }
            })
        }
        if (liProducts.length > 0 && aUniqueData1.length > 0) {
            aUniqueData1.forEach(u => {
                let iRec = liProducts.findIndex(f => f.PRODUCT_ID == u.product);
                if (iRec != -1) {
                    let cConfigChk = liProducts[iRec].CONFIGPROD_CHK;
                    if (cConfigChk != "X") {//Current Product is not ConfigProduct
                        let numberCheck = /^\d+$/.test(liProducts[iRec].REF_PRODID);
                        if (numberCheck == true) { //It is Only number with no special characteristics
                            u.product = GenF.removeSOleadzeros(liProducts[iRec].REF_PRODID)
                        }
                        else {
                            u.product = liProducts[iRec].REF_PRODID;
                        }
                    }
                }
            })
        }
        aUniqueData = uniqueList;
        //-------------------------------------------//
        jsonData = aUniqueData1;

        if (liProducts.length > 0) {//For comparison without leading zeroes
            liProducts.forEach(l => {
                if (l.CONFIGPROD_CHK != 'X') {
                    l.PRODUCT_ID = l.REF_PRODID;
                }
                let numberCheck = /^\d+$/.test(l.PRODUCT_ID);
                l.modifiedPRODUCT_ID = l.PRODUCT_ID;
                if (numberCheck == true) { //It is Only number with no special characteristics
                    l.modifiedPRODUCT_ID = GenF.removeSOleadzeros(l.PRODUCT_ID);
                    l.PRODUCT_ID = l.modifiedPRODUCT_ID;
                }
            })
        }

        aUniqueData.forEach((el, i) => {
            //find actual Product ID from liProducts
            var oProduct = liProducts.filter(pr => pr.modifiedPRODUCT_ID == el.PRODUCT_ID);
            //    if(oProduct.length>0 && oProduct[0].CONFIGPROD_CHK == 'X'){//if it is config product with zeroes
            if (oProduct.length > 0) {//if it is config product with zeroes
                if (oProduct.findIndex(f => f.CONFIGPROD_CHK == 'X') != -1) {//Config Product exists
                    let numberCheck = /^\d+$/.test(oProduct[0].REF_PRODID);
                    if (numberCheck == true) {
                        oProduct[0].PRODUCT_ID = oProduct[0].REF_PRODID;
                    }
                }
                else {//check if it is a ConfigProduct from CP_PRODUCT,then replace PRODUCT_ID
                    let aConfig = liConfigProducts.filter(pr => pr.modifiedPRODUCT_ID == el.PRODUCT_ID);
                    if (aConfig.length > 0) {
                        let numberCheck = /^\d+$/.test(aConfig[0].PRODUCT_ID);
                        if (numberCheck == true) {
                            oProduct[0].PRODUCT_ID = aConfig[0].PRODUCT_ID;
                        }
                    }
                }
            }
            else {//check if Product exists in CP_PRODUCT
                oProduct = liConfigProducts.filter(pr => pr.modifiedPRODUCT_ID == el.PRODUCT_ID);
            }
            if (i == 0) {//Invalid Product if it doesn't exist in CP_PARTIALPRODINTO AND CP_PRODUCT
                if (liProducts.filter(f => f.modifiedPRODUCT_ID == el.PRODUCT_ID).length == 0 &&
                    liConfigProducts.filter(f => f.modifiedPRODUCT_ID == el.PRODUCT_ID).length == 0) {
                    if (newProducts.filter(n => n == el.PRODUCT_ID).length == 0) {
                        newProducts.push(el.PRODUCT_ID);
                    }
                }
                if (newProducts.length == 0 && oProduct.length > 0) {//If valid Product
                    query = `SELECT * FROM "CP_UNIQUE_ID_HEADER"
                      WHERE "PRODUCT_ID" = '` + oProduct[0].PRODUCT_ID + `'
                      AND "EX_IDENTIFICATION" = '` +
                        el.EX_IDENTIFICATION + `'`;


                    prodQuery = `SELECT * FROM "V_PRODCLSCHARVAL"
                     WHERE "PRODUCT_ID" = '` + oProduct[0].PRODUCT_ID + `'`
                }
            }
            else {
                if (liProducts.filter(f => f.modifiedPRODUCT_ID == el.PRODUCT_ID).length == 0) {
                    if (newProducts.filter(n => n == el.PRODUCT_ID).length == 0) {
                        newProducts.push(el.PRODUCT_ID);
                    }
                }
                if (newProducts.length == 0 && oProduct.length > 0) {//If valid Product
                    query = query + `
                      OR "PRODUCT_ID" = '` + oProduct[0].PRODUCT_ID + `'
                      AND "EX_IDENTIFICATION" = '` +
                        el.EX_IDENTIFICATION + `'`;


                    prodQuery = prodQuery + `
                      OR "PRODUCT_ID" = '` + oProduct[0].PRODUCT_ID + `'`
                }
            }
        })
        if (newProducts.length > 0) {
            await GenF.jobSchMessage(' ', `The following are invalid product(s): " ${newProducts.toString()}`, req);
            return;
        }
        const liUnique = await cds.run(query);
        var sItemsQuery = "";
        /*if liUnique length is not zero then all the products from json exists in CP_UNIQUE_ID_HEADER,
        */
        const liProdcharItems = await cds.run(prodQuery);
        var liallProds = [];
        if (liUnique.length > 0) {
            liUnique.forEach((el, i) => {
                let numberCheck = /^\d+$/.test(el.PRODUCT_ID);
                el.modifiedPRODUCT_ID = el.PRODUCT_ID;
                if (numberCheck == true) { //It is Only number with no special characteristics
                    el.modifiedPRODUCT_ID = GenF.removeSOleadzeros(el.PRODUCT_ID);
                }
                if (i == 0) {
                    sItemsQuery = `SELECT * FROM "CP_UNIQUE_ID_ITEM"
                      WHERE "PRODUCT_ID" = '` + el.PRODUCT_ID + `'
                      AND "UNIQUE_ID" = '` + el.UNIQUE_ID + `'`;
                }
                else {
                    sItemsQuery = sItemsQuery + `
                      OR "PRODUCT_ID" = '` + el.PRODUCT_ID + `'
                      AND "UNIQUE_ID" = '` + el.UNIQUE_ID + `'`
                }
            })
            const liUniqueItems = await cds.run(sItemsQuery);

            liUnique.forEach(el => {
                let aChar = liUniqueItems.filter(f => f.UNIQUE_ID == el.UNIQUE_ID && f.PRODUCT_ID == el.PRODUCT_ID);
                let aProdChar = liProdcharItems.filter(f => f.PRODUCT_ID == el.PRODUCT_ID);
                let aJsonRec = aUniqueData.filter(j => j.PRODUCT_ID == el.modifiedPRODUCT_ID);
                const obj = {
                    UNIQUE_ID: el.UNIQUE_ID,
                    uniqueIDDescription: el.UNIQUE_DESC,
                    PRODUCT_ID: el.PRODUCT_ID,
                    EX_IDENTIFICATION: el.EX_IDENTIFICATION,
                    // LOCATION_ID: el.LOCATION_ID,
                    characteristics: aChar,
                    prodCharacteristics: aProdChar,
                    itemCharacteristics: aChar,
                    JSONPRODUCT_ID: (aJsonRec.length > 0) ? aJsonRec[0].PRODUCT_ID : el.PRODUCT_ID,
                    VALID_FROM: el.VALID_FROM,
                    VALID_TO: el.VALID_TO
                }
                aUniqueList.push(obj);
            })
        }
        aUniqueData.forEach((el, i) => {
            var oProduct = liProducts.filter(pr => pr.modifiedPRODUCT_ID == el.PRODUCT_ID);
            if (oProduct.length == 0) {//Take from CP_Product 
                oProduct = liConfigProducts.filter(pr => pr.modifiedPRODUCT_ID == el.PRODUCT_ID);
            }
            if (i == 0) {
                sItemsQuery = `SELECT * FROM "CP_UNIQUE_ID_ITEM"
                      WHERE "PRODUCT_ID" = '` + oProduct[0].PRODUCT_ID + `'`;
            }
            else {
                sItemsQuery = sItemsQuery + `
                      OR "PRODUCT_ID" = '` + oProduct[0].PRODUCT_ID + `'`
            }
        })
        const liUniqueItems = await cds.run(sItemsQuery);
        liallProds = liUniqueItems;

        aUniqueData.forEach(el => {
            //find actual Product ID from liProducts
            var oProduct = liProducts.filter(pr => pr.modifiedPRODUCT_ID == el.PRODUCT_ID);
            if (oProduct.length == 0) {//Take from CP_Product 
                oProduct = liConfigProducts.filter(pr => pr.modifiedPRODUCT_ID == el.PRODUCT_ID);
            }
            if (liUnique.filter(f => f.PRODUCT_ID == oProduct[0].PRODUCT_ID && f.EX_IDENTIFICATION == el.EX_IDENTIFICATION).length == 0) {
                let aProdChar = liProdcharItems.filter(f => f.PRODUCT_ID == oProduct[0].PRODUCT_ID);
                let aChar = liallProds.filter(f => f.PRODUCT_ID == oProduct[0].PRODUCT_ID);
                const obj = {
                    UNIQUE_ID: '',
                    uniqueIDDescription: el.uniqueIDDescription,
                    PRODUCT_ID: oProduct[0].PRODUCT_ID,
                    EX_IDENTIFICATION: el.EX_IDENTIFICATION,
                    characteristics: [],
                    prodCharacteristics: aProdChar,
                    itemCharacteristics: aChar,
                    JSONPRODUCT_ID: el.PRODUCT_ID,
                    VALID_FROM: el.VALID_FROM,
                    VALID_TO: el.VALID_TO
                }
                aUniqueList.push(obj);
            }
        })
        if (aUniqueList.length > 0) {
            let oResult = Catservicefn.validateJson(aUniqueList, jsonData);
            if (oResult.Type == "SUCCESS") {
                let liuniquechar = oResult.resultData, flag = oResult.resultCode;
                if (liuniquechar.length == 0) {
                    await GenF.jobSchMessage('X', "Creation/Updation of UniqueID(s) successful", req);
                    return;
                }
                const objCatFn = new Catservicefn();
                var liresults = [], lsresults = {};
                if (flag === 'B') {//from Browse Json file
                    for (var i = 0; i < liuniquechar.length; i++) {
                        liuniquechar[i].PRODUCT_ID = liuniquechar[i].product;
                        liuniquechar[i].UNIQUE_DESC = liuniquechar[i].uniqueIDDescription;
                        vID = await objCatFn.maintainUniqueHeader(flag, liuniquechar[i], liuniquechar, 'X');
                        if (vID !== '' && vID != "U") {
                            liresults = [];
                            let aNotCharData = Catservicefn.addNotMultiChar(liuniquechar[i].characteristics, liuniquechar[i].PRODUCT_ID, liProdcharItems);
                            if (aNotCharData.length > 0) {
                                liuniquechar[i].characteristics = liuniquechar[i].characteristics.concat(aNotCharData)
                            }
                            for (let j = 0; j < liuniquechar[i].characteristics.length; j++) {
                                lsresults.PRODUCT_ID = liuniquechar[i].PRODUCT_ID;
                                lsresults.UNIQUE_ID = vID;
                                lsresults.CHAR_NUM = liuniquechar[i].characteristics[j].characteristic.toString();
                                lsresults.CHARVAL_NUM = liuniquechar[i].characteristics[j].characteristicValue.toString();
                                //checking CHARVAL_NUM as well as the characteristics can be single or multi value
                                if (liresults.findIndex(el => el.CHAR_NUM == lsresults.CHAR_NUM && el.CHARVAL_NUM == lsresults.CHARVAL_NUM) === -1) {
                                    liresults.push(lsresults);
                                }
                                lsresults = {};
                            }
                            if (liresults.length > 0) {
                                try {
                                    await cds.run(INSERT.into("CP_UNIQUE_ID_ITEM").entries(liresults));
                                    logObj.Type = "SUCCESS";
                                    logObj.Description = "Creation/Updation of UniqueID(s) successful";
                                } catch (e) {
                                    logObj.Type = "ERROR";
                                    logObj.Description = "Creation Failed";
                                }
                            }

                        }
                        else if (vID == 'U') {
                            logObj.Type = "SUCCESS";
                            logObj.Description = "Creation/Updation of UniqueID(s) successful";
                        }
                        else {
                            logObj.Type = "ERROR";
                            logObj.Description = "Creation Failed";
                        }
                    }
                }
                else if (flag === 'D') {
                    for (var i = 0; i < liuniquechar.length; i++) {
                        liuniquechar[i].PRODUCT_ID = liuniquechar[i].product;
                        liuniquechar[i].UNIQUE_DESC = liuniquechar[i].uniqueIDDescription;
                        if (liuniquechar[i].UNIQUE_ID) {//if Unique ID exists,update header flag to true
                            liuniquechar[i].header = true;
                        }
                        if (liuniquechar[i].UNIQUE_ID == '' || liuniquechar[i].header == true) {
                            vID = await objCatFn.maintainUniqueHeader('B', liuniquechar[i], liuniquechar, 'X');
                            //For Update Mode,if UniqueID exists, delete characteristics as well
                            if (liuniquechar[i].UNIQUE_ID) {
                                vID = liuniquechar[i].UNIQUE_ID;
                                const obj = {
                                    UNIQUE_ID: vID,
                                    PRODUCT_ID: liuniquechar[i].product
                                }
                                await cds.delete("CP_UNIQUE_ID_ITEM", obj);
                            }
                        }
                        else {
                            vID = liuniquechar[i].UNIQUE_ID;
                            const obj = {
                                UNIQUE_ID: vID,
                                PRODUCT_ID: liuniquechar[i].product
                            }
                            await cds.delete("CP_UNIQUE_ID_ITEM", obj);
                        }
                        if (vID !== '' && vID != "U") {
                            liresults = [];
                            let aNotCharData = Catservicefn.addNotMultiChar(liuniquechar[i].characteristics, liuniquechar[i].PRODUCT_ID, liProdcharItems);
                            if (aNotCharData.length > 0) {
                                liuniquechar[i].characteristics = liuniquechar[i].characteristics.concat(aNotCharData)
                            }
                            for (let j = 0; j < liuniquechar[i].characteristics.length; j++) {
                                lsresults.PRODUCT_ID = liuniquechar[i].PRODUCT_ID;
                                lsresults.UNIQUE_ID = vID;
                                lsresults.CHAR_NUM = liuniquechar[i].characteristics[j].characteristic.toString();
                                lsresults.CHARVAL_NUM = liuniquechar[i].characteristics[j].characteristicValue.toString();
                                //checking CHARVAL_NUM as well as the characteristics can be single or multi value
                                if (liresults.findIndex(el => el.CHAR_NUM == lsresults.CHAR_NUM && el.CHARVAL_NUM == lsresults.CHARVAL_NUM) === -1) {
                                    liresults.push(lsresults);
                                }
                                lsresults = {};
                            }
                            if (liresults.length > 0) {
                                try {
                                    await cds.run(INSERT.into("CP_UNIQUE_ID_ITEM").entries(liresults));
                                    logObj.Type = "SUCCESS";
                                    logObj.Description = "Creation/Updation of UniqueID(s) successful";
                                } catch (e) {
                                    logObj.Type = "ERROR";
                                    logObj.Description = "Creation Failed";
                                }
                            }

                        }
                        else if (vID == 'U') {
                            logObj.Type = "SUCCESS";
                            logObj.Description = "Creation/Updation of UniqueID(s) successful";
                        }
                        else {
                            logObj.Type = "ERROR";
                            logObj.Description = "Creation Failed";
                        }
                    }
                }
                if (logObj.Type == "SUCCESS") {
                    await GenF.jobSchMessage('X', logObj.Description, req);
                    return;
                }
                else {
                    await GenF.jobSchMessage(' ', logObj.Description, req);
                    return;
                }
            }
            else {
                await GenF.jobSchMessage(' ', oResult.Description, req);
                return;
            }
        }
    })

