    srv.on("generateSeedOrders_old", async (req) => {
        const objSO = new SeedOrdService();
        let vDateFrom = req.data.FROMDATE;
        let vDateTo = req.data.TODATE;
        let aUniqueIdItems = [],
            aUIDItems = [];
        let dCurrDate = GenF.getCurrentDate();
        let aDates = [];
        let aCharValueOptionPercent = [];
        let iDateIndex = 0;
        let oSeedOrderData = {}, aSeedOrderData = [];
        let aSeedData = [];
        let iDiff = 0, iBaseQty = 0;
        let aCharValues = [];
        let arr = [];
        let aFilcharUID = [], aFilUIDs = [];
        let oCharValOPT = {};
        let aCharOpt = [], oCharOpt = {};
        let iCount = 0, iDatesLength = 0, iCharLength = 0;
        let oResponse = {};
        let acharUID = [], aCharUIDItems = [];

        // Get Date Series based on From and To dates entered
        aDates = await obibpfucntions.generateDateseries(vDateFrom, vDateTo);
        if (aDates.length > 0) {
            iDatesLength = aDates.length;
        }

        //  Get Characteristic Value Percentages
        aCharValueOptionPercent = await cds.run(`SELECT A.CHAR_NUM,
                                                        A.CHARVAL_NUM,
                                                        A.OPT_PERCENT
                                                   FROM CP_CHAR_VALUE_OPTPERCENT AS A
                                                   INNER JOIN V_PRODCLSCHARVAL AS B
                                                      ON A.CHAR_NUM = B.CHAR_NUM
                                                     AND A.CHARVAL_NUM = B.CHARVAL_NUM
                                                   WHERE B.PRODUCT_ID = '${req.data.PRODUCT_ID}'
                                                   ORDER BY A.CHAR_NUM,
                                                            A.CHARVAL_NUM`);
        // Get Unique Ids with Configuration details 
        aUniqueIdItems = await cds.run(`SELECT *
                                          FROM V_UNIQUE_ID_ITEM
                                         WHERE PRODUCT_ID = '${req.data.PRODUCT_ID}'
                                           AND UID_TYPE = 'U'
                                           AND ( VALID_FROM <= '${dCurrDate}'
                                           AND VALID_TO >= '${dCurrDate}')
                                           AND CHAR_NUM IN (SELECT DISTINCT CHAR_NUM FROM CP_CHAR_VALUE_OPTPERCENT)
                                         ORDER BY UNIQUE_ID,
                                                  CHAR_NUM`);

        // Below code is to group each unique id and its config as Item        
        if (aUniqueIdItems.length > 0) {
            aUIDItems = aUniqueIdItems.reduce((aUID, curr) => {
                let CHARVALUE = '';
                const {
                    UNIQUE_ID,
                    CHAR_NUM,
                    CHARVAL_NUM
                } = curr;
                const findObj = aUID.find((o) => o.UNIQUE_ID === UNIQUE_ID);
                if (!findObj) {
                    CHARVALUE = CHARVAL_NUM;
                    aUID.push({ UNIQUE_ID, CHARVALUE });
                } else {
                    findObj.CHARVALUE = findObj.CHARVALUE + ',' + CHARVAL_NUM;
                }
                return aUID;
            }, []);
        }

        // Get all the distict unique id combinations based on characteristics from CP_CHARVAL_OPTPERCENT
        if (aUIDItems.length > 0) {
            const keys = ['CHARVALUE'];
            aUIDItems.sort(GenF.dynamicSortMultiple("CHARVALUE"));
            aUIDItems = GenF.removeDuplicate(aUIDItems, keys);
            arr = aUIDItems.map(function (el) { return el.UNIQUE_ID });
            console.log(aUIDItems);
        }

        // Get Count of Unique Ids for selected Characteristics and values
        acharUID = await cds.run(`SELECT 
                                            CHAR_NUM,
                                            CHARVAL_NUM,
                                            COUNT(*) as UID_COUNT
                                        FROM V_UNIQUE_ID_ITEM
                                       WHERE UNIQUE_ID IN (`+ arr.toString() + `)
                                         AND PRODUCT_ID = '${req.data.PRODUCT_ID}'
                                         AND CHAR_NUM IN (SELECT DISTINCT CHAR_NUM FROM CP_CHAR_VALUE_OPTPERCENT)
                                        GROUP BY CHAR_NUM,
                                                CHARVAL_NUM
                                        ORDER BY CHAR_NUM,
                                                CHARVAL_NUM                                    
                                       `);
        // Get Unique Ids and its configurations for distinct combinations of UIDs filtered
        aCharUIDItems = await cds.run(`SELECT 
                                                UNIQUE_ID,
                                                CHAR_NUM,
                                                CHARVAL_NUM                                                
                                            FROM V_UNIQUE_ID_ITEM
                                        WHERE UNIQUE_ID IN (`+ arr.toString() + `)
                                          AND PRODUCT_ID = '${req.data.PRODUCT_ID}'
                                          AND CHAR_NUM IN (SELECT DISTINCT CHAR_NUM FROM CP_CHAR_VALUE_OPTPERCENT)
                                        ORDER BY UNIQUE_ID,
                                                 CHAR_NUM,
                                                 CHARVAL_NUM                              
                                        `);

        //  Below code is to get the highest factor for each characteristic based on option percent for values
        //  and also populate the unique ids with current char value
        for (let iOpt = 0; iOpt < aCharValueOptionPercent.length; iOpt++) {
            if (
                iOpt === 0 ||
                aCharValueOptionPercent[iOpt].CHAR_NUM !==
                aCharValueOptionPercent[GenF.subOne(iOpt, aCharValueOptionPercent.length)].CHAR_NUM
            ) {
                oCharOpt = {};
                oCharOpt.CHAR_NUM = aCharValueOptionPercent[iOpt].CHAR_NUM;
                oCharOpt.CHARVALUE = [];
                oCharOpt.FACTOR = 0;
            }

            oCharValOPT.CHAR_NUM = aCharValueOptionPercent[iOpt].CHAR_NUM;
            oCharValOPT.CHARVAL_NUM = aCharValueOptionPercent[iOpt].CHARVAL_NUM;
            oCharValOPT.OPT_PERCENT = aCharValueOptionPercent[iOpt].OPT_PERCENT;

            aFilcharUID = [];
            aFilUIDs = [];

            // Filter to get Count of Unique Ids
            aFilcharUID = acharUID.filter(function (aUID) {
                return (
                    aUID.CHAR_NUM === aCharValueOptionPercent[iOpt].CHAR_NUM &&
                    aUID.CHARVAL_NUM === aCharValueOptionPercent[iOpt].CHARVAL_NUM

                );
            });

            // Filter to get Unique Id Numbers
            aFilUIDs = aCharUIDItems.filter(function (aUID) {
                return (
                    aUID.CHAR_NUM === aCharValueOptionPercent[iOpt].CHAR_NUM &&
                    aUID.CHARVAL_NUM === aCharValueOptionPercent[iOpt].CHARVAL_NUM

                );
            });

            // 
            if (aFilUIDs.length > 0) {
                oCharValOPT.UNIQUE_IDS = aFilUIDs.map((item) => item.UNIQUE_ID);
            }


            if (aFilcharUID.length > 0) {
                oCharValOPT.UID_COUNT = aFilcharUID[0].UID_COUNT;
                oCharValOPT.FACTOR = 1;
                oCharValOPT.OPT_QTY = 0;
                if (aFilcharUID[0].UID_COUNT > oCharValOPT.OPT_PERCENT) {
                    oCharValOPT.FACTOR = aFilcharUID[0].UID_COUNT / oCharValOPT.OPT_PERCENT;
                }
            }

            oCharOpt.CHARVALUE.push(GenF.parse(oCharValOPT));

            if (oCharValOPT.FACTOR > oCharOpt.FACTOR) {
                oCharOpt.FACTOR = oCharValOPT.FACTOR;
            }


            if (iOpt === GenF.addOne(iOpt, aCharValueOptionPercent.length) ||
                aCharValueOptionPercent[iOpt].CHAR_NUM !== aCharValueOptionPercent[GenF.addOne(iOpt, aCharValueOptionPercent.length)].CHAR_NUM) {
                oCharOpt.FACTOR = Math.ceil(oCharOpt.FACTOR);

                aCharOpt.push(GenF.parse(oCharOpt));

            }

        }

        if (aCharOpt.length > 0) {
            aCharOpt.sort(GenF.dynamicSortMultiple("CHAR_NUM", "FACTOR desc"));

            iCount = 0;
            iCharLength = aCharOpt.length - 1;

            while (iDateIndex < iDatesLength - 1) {
                aSeedData = [];
                oResponse = await objSO.genSeedOrderData(aDates, iDateIndex, aCharOpt, iCount, req);
                aSeedData = oResponse.SEEDDATA;
                iDateIndex = oResponse.DATEINDEX;
                if (aSeedOrderData.length === 0) {
                    aSeedOrderData = aSeedData;
                } else {
                    aSeedOrderData = [...aSeedOrderData, ...aSeedData];
                }

                iCount = 1;
            }
        }

        if (aSeedOrderData.length > 0) {
            oResponse = {};
            let sSEEDDATA = JSON.stringify(aSeedOrderData);
            // Generate SeedOrders
            oResponse = await objSO.genSeedOrders('C', sSEEDDATA);
            if (oResponse.bFlag === true) {
                await GenF.jobSchMessage('X', oResponse.Message, req);
            } else {
                await GenF.jobSchMessage('', oResponse.Message, req);
            }
            console.log(oResponse);
        } else {
            await GenF.jobSchMessage('X', 'No data generated for SeedOrders', req);
        }

    });
