    srv.on("getCFUsers", async () => {
        var promiseArray = [];
        var exec = require('child_process').exec;
        const {
            spawn
        } = require('child_process');
        var aUsers = [];
        console.log(process.env.NODE_ENV, "env")
        console.log(process.env, "env2")
        const API_ENDPOINT = 'https://api.cf.us10.hana.ondemand.com',
            sUserName = '',
            sPassword = '';
        try {
            let promiseReq = new Promise(async function (resolve, _reject) {
                //first install cf to shell, since after deployment shell won't have CF
                await exec('mkdir -p ~/bin && curl -sSL "https://packages.cloudfoundry.org/stable?release=linux64-binary&source=github" | tar -zx -C ~/bin', async (error1, res1) => {
                    if (error1) {
                        console.log(`Error installing cf: ${error1.message}`);
                        return resolve(aUsers);
                    }
                    await exec('cf api https://api.cf.us10.hana.ondemand.com');
                    const cfLogin = spawn('cf', ['login', '-a', API_ENDPOINT, '-u', sUserName, '-p', sPassword]);
                    var count = 0;
                    cfLogin.stdout.on('data', (data) => {
                        count++;
                        if (count == 2) {
                            exec('cf orgs', async (error2, result2) => {
                                if (!error2) {
                                    let aOrgs = result2.split('name\n')[1].split('\n');
                                    aOrgs = aOrgs.filter(f => f != '');
                                    if (aOrgs.length > 0) {
                                        var iLoopCount = 0;
                                        for (var i = 0; i < aOrgs.length; i++) {
                                            if (aOrgs[i]) {
                                                exec(`cf org-users ${aOrgs[i]} -a`, async (error3, result3) => {
                                                    if (!error3) {
                                                        iLoopCount++;
                                                        var aOrgusers = '';
                                                        if (result3.toString().includes('ORG USERS')) {
                                                            aOrgusers = result3.split("ORG USERS")[1].toString().replace(/\n/g, '').split("(sap.ids)");
                                                        } else { //Deployment
                                                            aOrgusers = result3.split("USERS")[1].toString().split("\n");
                                                        }
                                                        if (aOrgusers) {
                                                            Array.from(aOrgusers).forEach(u => {
                                                                if (u) {
                                                                    const obj = {
                                                                        "USERNAME": u.toString().split("(")[0].trim(),
                                                                    }
                                                                    //To Prevent duplicate records insertion
                                                                    if (aUsers.findIndex(f => f.USERNAME == obj.USERNAME) == -1) {
                                                                        aUsers.push(obj);
                                                                    }
                                                                }
                                                            })
                                                            if (iLoopCount == aOrgs.length) {
                                                                return resolve(aUsers);
                                                            }
                                                        }
                                                    } else {
                                                        iLoopCount++;
                                                    }
                                                })
                                            }
                                        }
                                    } else {
                                        console.log("No organizations!");
                                        return resolve(aUsers);
                                    }
                                } else {
                                    console.log(error2);
                                    return resolve(aUsers);
                                }
                            })
                        }
                    });
                })
            });
            promiseArray.push(promiseReq);
        } catch (ex) {
            console.log(ex);
        }
        try {
            await Promise.all(promiseArray);
            return aUsers;
        } catch (ex) {
            return [];
        }
    })

    //Services for insert,Update  User Preferences
    srv.on("maintainUserPreferences", async (req) => {
        var flag = req.data.FLAG;
        var oData = JSON.parse(req.data.PREFERENCEDATA), responseMessage = "", errorFlag = false;
        if (flag == 'C' || flag == "U") {
            let logData = GenF.getLogInput(flag, req, oData.CREATED_BY);
            let oResult = {
                PARAMETER: oData.PARAMETER,
                DESCRIPTION: oData.DESCRIPTION,
                PARAMETER_VALUE: oData.PARAMETER_VALUE
            }
            oResult = Object.assign(oResult, logData);
            if (flag == 'C') {
                try {
                    await cds.run(INSERT.into("CP_USER_PREFERENCES").entries(oResult));
                    responseMessage = "Creation Successful";
                } catch (ex) {
                    if (ex.message == 'ENTITY_ALREADY_EXISTS') {
                        responseMessage = `Creation Failed, Preference: ${oData.PARAMETER} already Exists!`;
                    }
                    else {
                        responseMessage = "Creation Failed";
                    }
                    errorFlag = true;
                }

            } else {
                try {
                    await UPDATE`CP_USER_PREFERENCES`
                        .with({
                            DESCRIPTION: oData.DESCRIPTION,
                            PARAMETER_VALUE: oData.PARAMETER_VALUE.toString(),
                            CHANGED_BY: logData.CHANGED_BY,
                            CHANGED_DATE: logData.CHANGED_DATE,
                            CHANGED_TIME: logData.CHANGED_TIME
                        })
                        .where(`PARAMETER = '${oData.PARAMETER}'`);
                    responseMessage = "Updation Successful";
                } catch {
                    responseMessage = "Updation Failed";
                    errorFlag = true;
                }
            }
        }
        return {
            msg: responseMessage,
            error: errorFlag
        };
    })
    //service to get all  Timezones
    srv.on("getTimeZones", async (req) => {
        const moment = require('moment-timezone');
        const allTimezones = moment.tz.names();
        // Map timezones to include their formatted offset and raw offset considering DST dynamically
        const timezoneData = allTimezones.map(timezone => {
            // Get timezone offset at the current moment to account for DST
            const now = moment();
            const offset = now.tz(timezone).utcOffset(); // Dynamic DST consideration
            const sign = offset >= 0 ? '+' : '-';
            const absOffset = Math.abs(offset);
            const hours = Math.floor(absOffset / 60);
            const minutes = absOffset % 60;
            const formattedOffset = `UTC${sign}${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}`;
            return {
                timezone,
                formattedOffset,
                offset,
                simpleName: timezone.split('/').pop().replace('_', ' ')
            };
        });
        // Group by the formattedOffset
        const groupedByOffset = timezoneData.reduce((acc, curr) => {
            if (!acc[curr.formattedOffset]) {
                acc[curr.formattedOffset] = [];
            }
            acc[curr.formattedOffset].push(curr.simpleName);
            return acc;
        }, {});
        // Convert groups into the desired string format and sort by offset considering DST dynamically
        const groupedFormattedTimezones = Object.keys(groupedByOffset).sort((a, b) => {
            // Extract hours and minutes for sorting
            const pattern = /UTC([+-]\d+):(\d+)/;
            const offsetA = parseInt(a.match(pattern)[1]) * 60 + parseInt(a.match(pattern)[2]);
            const offsetB = parseInt(b.match(pattern)[1]) * 60 + parseInt(b.match(pattern)[2]);
            return offsetA - offsetB;
        }).map(offset => {
            // Group and format timezones dynamically considering DST
            return `(${offset}) - ${groupedByOffset[offset].join(',')}`;
        });

        return JSON.stringify(groupedFormattedTimezones);
    });
