    //Function to add Location Product characteristics
    srv.on("getLOCPRODCHAR", async (req) => {
        let lsResutls = {};
        let liResults = [];
        let initalData = {};
        let fetchedResults, responseMessage = "";
        initalData = JSON.parse(req.data.LOCPRODCHAR);
        fetchedResults = await cds.run(`SELECT
            LOCATION_ID,
            PRODUCT_ID,
            CHARVAL_DESC,
            CHAR_DESC,
            CHAR_NUM,
            CHAR_VALUE                                                
            FROM CP_LOC_PROD_CHARACTERISTICS
            WHERE LOCATION_ID= '${initalData[0].LOCATION_ID}'  
            AND PRODUCT_ID = '${initalData[0].PRODUCT_ID}'`);
        if (fetchedResults.length > 0) {
            await cds.run(`DELETE  FROM "CP_LOC_PROD_CHARACTERISTICS"
                                WHERE LOCATION_ID = '${initalData[0].LOCATION_ID}'
                                AND PRODUCT_ID = '${initalData[0].PRODUCT_ID}'`);
            responseMessage = "Successfully Unselected."
        }
        if (req.data.FLAG === "X") {
            let count = 0;
            for (var i = 0; i < initalData.length; i++) {
                lsResutls.LOCATION_ID = initalData[i].LOCATION_ID;
                lsResutls.PRODUCT_ID = initalData[i].PRODUCT_ID;
                lsResutls.CHAR_NUM = initalData[i].CHAR_NUM;
                lsResutls.CHAR_DESC = initalData[i].CHAR_DESC;
                lsResutls.CHAR_VALUE = initalData[i].CHAR_VALUE;
                lsResutls.CHARVAL_DESC = initalData[i].CHARVAL_DESC;
                lsResutls.CHARVAL_NUM = initalData[i].CHAR_VALUE;
                liResults.push(lsResutls);
                try {
                    await cds.run(INSERT.into("CP_LOC_PROD_CHARACTERISTICS").entries(lsResutls));
                    count++;
                } catch (e) {
                    count--;
                }
                lsResutls = {};
            }
            if (count === initalData.length) {
                responseMessage = "Successfully Created";
            }
            else if (count === 0) {
                responseMessage = "Creation Failed";
            }
            else {
                responseMessage = "Few characteristics have failed to save";
            }
            return responseMessage;
        }
        else if (req.data.FLAG === "D") {
            return responseMessage;
        }
    })

