    srv.on("getBOMLocProdNode", async (req) => {
        let sQuery = `SELECT DISTINCT 
        A."LOCATION_ID",
        A."LOCATION_DESC",
        A."PRODUCT_ID",
        A."PROD_DESC",
        A."PROD_TYPE",
        B."ACCESS_NODE"
    FROM "V_LOCPROD" AS A
     LEFT OUTER JOIN "CP_PROD_ACCNODE" AS B
     ON A.LOCATION_ID = B.LOCATION_ID
     AND A.PRODUCT_ID = B.PRODUCT_ID
        INNER JOIN "CP_BOM_MAT" AS C
    ON A.LOCATION_ID = C.LOCATION_ID
    AND A.PRODUCT_ID = C.MAT_PARENT
    INNER JOIN "CP_PRODUCT" AS D
    ON D.PROD_TYPE = A.PROD_TYPE`;
        var aData = await cds.run(sQuery);
        if (aData.length > 0 && req.headers['x-user-id']) {
            let aRoles = await cds.run(`SELECT DISTINCT REF_PRODID FROM "V_ROLES_LOCPROD" WHERE USER='${req.headers['x-user-id']}'`);
            if (aRoles.length == 0) {
                aData = [];
            }
            else {
                const refIds = new Set(aRoles.map(x => x.REF_PRODID));
                aData = aData.filter(x => refIds.has(x.PRODUCT_ID));
            }
        }
        return JSON.stringify(aData);
    })
