    srv.on("saveKeyFigMasterData", async (req) => {
        const saveData = [];
        const returnMessage = "Sucessfully saved data";
        const data = JSON.parse(req.data.keyFigData);
        if (data && data.length > 0) {
            try {
                const keyFigData = await cds.run(`SELECT * FROM "CP_KEY_FIGURE_MASTER"`)
                for (let index = 0; index < data.length; index++) {
                    const element = data[index];
                    let foundObj = keyFigData.find(item => item.KEY_FIG_ID == element.KEY_FIG_ID)
                    if (foundObj) {
                        await UPDATE`CP_KEY_FIGURE_MASTER`
                            .with({
                                KEY_FIG_DESC: element.KEY_FIG_DESC,
                                KEY_FIG_DESCRIPTION: element.KEY_FIG_DESCRIPTION,
                                DISPLAY_ORDER: element.DISPLAY_ORDER,
                                PRIORITY_ORDER: element.PRIORITY_ORDER
                            }).where(`KEY_FIG_ID = '${element.KEY_FIG_ID}'`);
                    } else {
                        const obj = Object.assign({}, element);
                        saveData.push(obj);
                    }
                }
                if (saveData.length > 0) {
                    await cds.run(INSERT.into("CP_KEY_FIGURE_MASTER").entries(saveData));
                }
            } catch (error) {
                returnMessage = error.message;
            }
        }
        return returnMessage;
    })
