    srv.on("genTmpUniqueID", async req => {
        let liTmpHeader = [];
        let liTmpItem = [];
        let liTmpdata = [];
        let lsHeader = {};
        //  let   lsItem = {};
        let GenFlag = '';
        var responseMessage;


        liTmpHeader = JSON.parse(req.data.HeadData);
        GenFlag = req.data.Flag;

        let count = 0;
        let lsresults = {};
        for (let i = 0; i < liTmpHeader.length; i++) {

            lsresults.PRODUCT_ID = liTmpHeader[i].PRODUCT_ID;
            lsresults.PROJECT_ID = liTmpHeader[i].PROJECT_ID;
            lsresults.TMP_UNIQUE_ID = liTmpHeader[i].TMP_UNIQUE_ID;
            lsresults.REF_UNIQUE_ID = liTmpHeader[i].REF_UNIQUE_ID;
            lsresults.WEIGHTAGE = liTmpHeader[i].WEIGHTAGE;
            lsresults.VALID_FROM = liTmpHeader[i].VALID_FROM;
            lsresults.VALID_TO = liTmpHeader[i].VALID_TO;

            try {
                await UPDATE`CP_TMP_UNIQUE_ID_HEADER`
                    .with({
                        WEIGHTAGE: lsresults.WEIGHTAGE,
                        VALID_FROM: lsresults.VALID_FROM,
                        VALID_TO: lsresults.VALID_TO
                    })
                    .where(`PRODUCT_ID = '${lsresults.PRODUCT_ID}'
                                          AND PROJECT_ID = '${lsresults.PROJECT_ID}'
                                          AND TMP_UNIQUE_ID = '${lsresults.TMP_UNIQUE_ID}'
                                          AND REF_UNIQUE_ID = '${lsresults.REF_UNIQUE_ID}'`);
                count = count + 1;
                lsresults = {};

            } catch (e) {
                count = count - 1;
            }
        }
        if (count === liTmpHeader.length) {
            responseMessage = "Successfully updated the Unique ID details";
        } else {
            responseMessage = "Failed to update the Unique ID details";
        }

        return responseMessage;

    });

