    srv.on("funcCharValBucket", async (req) => {

        let oNumData = [];

        //  Get Characteristic Value Percentages filtered by CHAR_TYPE == "NUM"
        //commented on 04/05/2025 Pradeep for common filter usage
        // oNumData = await cds.run(`SELECT DISTINCT A.CLASS_NUM,
        //                                 A.CHAR_NUM,
        //                                 A.CHAR_NAME,
        //                                 A.CHAR_DESC,
        //                                 A.CHAR_TYPE,
        //                                 B.PRODUCT_ID,
        //                                 C.PROD_DESC
        //                                 FROM
        //                                 CP_CHARACTERISTICS AS A
        //                                 INNER JOIN CP_PRODUCT_CLASS AS B
        //                                 ON A.CLASS_NUM = B.CLASS_NUM
        //                                 INNER JOIN CP_PRODUCT AS C
        //                                 ON B.PRODUCT_ID = C.PRODUCT_ID
        //                                 WHERE A.CHAR_TYPE = 'NUM'`);
        let sQuery = `SELECT DISTINCT A.CLASS_NUM,
                                         A.CHAR_NUM,
                                         A.CHAR_NAME,
                                         A.CHAR_DESC,
                                         A.CHAR_TYPE,
                                         B.PRODUCT_ID,
                                         C.PROD_DESC
                                         FROM
                                         CP_CHARACTERISTICS AS A
                                         INNER JOIN CP_PRODUCT_CLASS AS B
                                         ON A.CLASS_NUM = B.CLASS_NUM
                                         INNER JOIN V_FACTORYLOC AS C
                                         ON B.PRODUCT_ID = C.REF_PRODID
                                         WHERE A.CHAR_TYPE = 'NUM'`

        oNumData = await cds.run(sQuery);
        if (oNumData.length > 0 && req.headers['x-user-id']) {
            let aRoles = await cds.run(`SELECT DISTINCT REF_PRODID FROM "V_ROLES_LOCPROD" WHERE USER='${req.headers['x-user-id']}'`);
            if (aRoles.length == 0) {
                oNumData = [];
            }
            else {
                const refIds = new Set(aRoles.map(x => x.REF_PRODID));
                oNumData = oNumData.filter(x => refIds.has(x.PRODUCT_ID));
            }
        }
        const jsonData = JSON.stringify(oNumData)
        return new Promise((resolve, reject) => {
            zlib.gzip(jsonData, (err, buffer) => {
                if (err) reject(err);
                resolve({ compressed: buffer.toString("base64") });
            });
        });
    });

