    srv.on("genProductBatch", async (req) => {
        let lsResults = {};
        let liResults = {};
        let finalResults = [];
        let lMessage = 'Entry exists for Loc/Product: ', vErrFlag = '', responseMessage1 = 'Entries already exists for Loc/Product';
        lsResults = JSON.parse(req.data.LocProdData);
        if (lsResults.length > 0) {
            for (var i = 0; i < lsResults.length; i++) {
                let liFactoryLoc = [];
                liFactoryLoc = await cds.run(`
                                                SELECT *
                                                  FROM CP_FACTORY_SALESLOC
                                                 WHERE LOCATION_ID = '${lsResults[i].LOCATION_ID}'
                                                   AND PLAN_LOC = '${lsResults[i].PLAN_LOC}'
                                                   AND FACTORY_LOC = '${lsResults[i].FACTORY_LOC}'
                                                   AND PRODUCT_ID = '${lsResults[i].PRODUCT_ID}'`);

                if (liFactoryLoc.length > 0) {
                    lMessage = lMessage + lsResults[i].LOCATION_ID.toString() + '/' + lsResults[i].PRODUCT_ID.toString() + '  ';
                    vErrFlag = 'X'
                }
                else {
                    liResults.LOCATION_ID = lsResults[i].LOCATION_ID;
                    liResults.PRODUCT_ID = lsResults[i].PRODUCT_ID;
                    liResults.PLAN_LOC = lsResults[i].PLAN_LOC;
                    liResults.FACTORY_LOC = lsResults[i].FACTORY_LOC;
                    finalResults.push(liResults)
                }
                liResults = {};
            }
            try {
                if (finalResults.length > 0) {
                    await cds.run(INSERT.into("CP_FACTORY_SALESLOC").entries(finalResults));
                    if (vErrFlag === 'X') {
                        responseMessage1 = lMessage + ', Creating the remaining entries'
                    }
                    else {
                        responseMessage1 = "Created Successfully";
                    }
                }
                await GenF.jobSchMessage('X', responseMessage1, req);

            } catch (e) {
                responseMessage1 = "Creation Failed";
                await GenF.jobSchMessage('', responseMessage1, req);
            }
        } else {
            await GenF.jobSchMessage('X', "Entry exists for Loc/Product", req);
        }
    });

    srv.on("modifyCustomerGroup", async (req) => {
        // req.data.customerGroupData = JSON.stringify([{"PRODUCT_ID":"VCP_1500","GROUP_NAME":"Gro","WEIGHTAGE":3,"CHANGED_BY":"xhyz@sbpcorp.in"}]);
        let aData = JSON.parse(req.data.customerGroupData);
        var sFlag = req.data.Flag, sResponse = '';
        let User = aData[0].CHANGED_BY;
        let DateValue = new Date().toISOString().split('T')[0];
        let timeValue = new Date().toTimeString().split(" ")[0];

        // for (var i = 0; i < aData.length; i++) {
        //     aData[i].CHANGED_BY = User;
        //     aData[i].CHANGED_DATE = DateValue;
        //     aData[i].CHANGED_TIME = timeValue;

        // }

        aData.forEach(el => {
            el.CHANGED_BY = User;
            el.CHANGED_DATE = DateValue;
            el.CHANGED_TIME = timeValue;
        });

        if (sFlag == 'C') {
            if (aData?.length > 0) {
                try {
                    await cds.run(INSERT.into("CP_CHARACTERISTIC_GROUPS").entries(aData));
                    sResponse = 'Customer Group creation Successful'
                }
                catch {
                    sResponse = 'Customer Group creation Failed.'
                }
            }
        }
        else if (sFlag == 'U') {
            if (aData?.length > 0) {
                for (var i = 0; i < aData.length; i++) {
                    try {
                        await UPDATE`CP_CHARACTERISTIC_GROUPS`
                            .with({
                                WEIGHTAGE: aData[i].WEIGHTAGE,
                                CHANGED_BY: aData[i].CHANGED_BY,
                                CHANGED_DATE: DateValue,
                                CHANGED_TIME: timeValue


                            })
                            .where(`PRODUCT_ID = '${aData[i].PRODUCT_ID}'
                                    AND GROUP_NAME = '${aData[i].GROUP_NAME}'`);
                        sResponse = 'Customer Group updation Successful'
                    }
                    catch (ex) {
                        sResponse = 'Customer Group updation Failed.'
                    }
                }
            }
        }
        else {
            if (aData?.length > 0) {
                for (var i = 0; i < aData.length; i++) {
                    try {
                        await cds.run(`DELETE FROM "CP_CHARACTERISTIC_GROUPS" WHERE PRODUCT_ID = '${aData[i].PRODUCT_ID}'
                                    AND  GROUP_NAME = '${aData[i].GROUP_NAME}'
                                AND WEIGHTAGE = '${aData[i].WEIGHTAGE}'`)
                        sResponse = 'Customer Group deletion Successful'
                    }
                    catch (ex) {
                        sResponse = 'Customer Group deletion Failed.'
                    }
                }
            }
        }
        return sResponse;
    })

    srv.on("maintainLocProdProfile", async (req) => {
        let aData = JSON.parse(req.data.LocProdData);
        let sResponse = 'No data to update'
        if (aData.length > 0) {
            let tabData = await cds.run(`
                    SELECT *
                    FROM CP_PROFILE_LOC_PROD`);
            let logData = GenF.getLogInput('C', req, aData[0].CREATED_BY);

            let DateValue = new Date().toISOString().split('T')[0];
            let timeValue = new Date().toTimeString().split(" ")[0];
            for (let i = 0; i < aData.length; i++) {
                let obj = {
                    LOCATION_ID: aData[i].LOCATION_ID,
                    PRODUCT_ID: aData[i].PRODUCT_ID,
                    PREDICTION_PROFILE: aData[i].PREDICTION_PROFILE,
                    PLANNING_PROFILE: aData[i].PLANNING_PROFILE,
                    FORECASTING_PROFILE: aData[i].FORECASTING_PROFILE,
                    OPTION_PERCENT: aData[i].OPTION_PERCENT,
                    OPTIMIZATION_PROFILE: aData[i].OPTIMIZATION_PROFILE,
                    PERIOD_PROFILE: aData[i].PERIOD_PROFILE,
                    DERIVED_PROFILE: aData[i].DERIVED_PROFILE,
                    CREATED_BY: logData.CREATED_BY,
                    CREATED_DATE: logData.CREATED_DATE,
                    CREATED_TIME: timeValue
                }
                let dataCount = tabData.filter(el => el.LOCATION_ID === obj.LOCATION_ID &&
                    el.PRODUCT_ID === obj.PRODUCT_ID);

                if (dataCount.length > 0) {
                    try {
                        await UPDATE`CP_PROFILE_LOC_PROD`
                            .with({
                                PREDICTION_PROFILE: obj.PREDICTION_PROFILE,
                                PLANNING_PROFILE: obj.PLANNING_PROFILE,
                                FORECASTING_PROFILE: obj.FORECASTING_PROFILE,
                                OPTION_PERCENT: obj.OPTION_PERCENT,
                                OPTIMIZATION_PROFILE: obj.OPTIMIZATION_PROFILE,
                                PERIOD_PROFILE: obj.PERIOD_PROFILE,
                                DERIVED_PROFILE: obj.DERIVED_PROFILE,
                                CHANGED_BY: logData.CREATED_BY,
                                CHANGED_DATE: DateValue,
                                CHANGED_TIME: timeValue

                            })
                            .where(`LOCATION_ID = '${obj.LOCATION_ID}'
                                and PRODUCT_ID = '${obj.PRODUCT_ID}'`);
                        sResponse = "Successfully updated the data";
                    } catch (error) {
                        sResponse = "Failed to update the data";
                        console.log(error.message);
                    }
                } else {
                    try {
                        await cds.run(INSERT.into("CP_PROFILE_LOC_PROD").entries(obj));
                        sResponse = 'Successfully updated the data';
                    }
                    catch (error) {
                        sResponse = 'Failed to update the data.';
                        console.log(error.message);
                    }
                }
            }
        }


        return sResponse;

    });


