    srv.on("updateCharConfig", async (req) => {
        let aData = JSON.parse(req.data.CHARDATA);
        var responseMessage = 'Updation successful';
        if (aData?.length > 0) {
            for (var a = 0; a < aData?.length; a++) {
                let el = aData[a];
                try {
                    await UPDATE`CP_VARCHAR_PS`
                        .with({
                            CHAR_TYPE: el.CHAR_TYPE,
                            SEQUENCE: el.SEQUENCE
                        })
                        .where(`PRODUCT_ID = '${el.PRODUCT_ID}'
                                AND CHAR_NUM = '${el.CHAR_NUM}'`);
                } catch (e) {
                    responseMessage = "Updation failed";
                }
            }
        }
        else {
            responseMessage = 'Upload Valid Data'
        }
        return responseMessage;
    })

    //Function for Option Percentage Threshold application to Create,Update and Delete
    srv.on("maintainOptThreshold", async (req) => {
        let aData = JSON.parse(req.data.LocProdData), cResponse = 'E';
        try {
            if (req.data.FLAG == 'C') {//Create
                await cds.run(INSERT.into("CP_OPTION_PERCENT_THRESHOLD").entries(aData));
                cResponse = 'S'
            }
            else {
                for (var a = 0; a < aData?.length; a++) {
                    let el = aData[a];
                    if (req.data.FLAG == 'U') {
                        await UPDATE`CP_OPTION_PERCENT_THRESHOLD`
                            .with({
                                MINIMUM: el.MINIMUM,
                                MAXIMUM: el.MAXIMUM
                            })
                            .where(`PRODUCT_ID = '${el.PRODUCT_ID}'
                        AND CLASS_NAME = '${el.CLASS_NAME}'
                        AND CHAR_NAME = '${el.CHAR_NAME}'`);
                        cResponse = 'S';
                    }
                    else if (req.data.FLAG == 'D') {
                        await cds.run(
                            `DELETE FROM "CP_OPTION_PERCENT_THRESHOLD" 
                        WHERE "PRODUCT_ID" = '${el.PRODUCT_ID}'
                        AND "CLASS_NAME" = '${el.CLASS_NAME}'
                        AND "CHAR_NAME" = '${el.CHAR_NAME}'`);
                        cResponse = 'S';
                    }
                }
            }
        }
        catch (ex) {
            cResponse = 'E';
        }
        return cResponse;
    })

    srv.on("deletePlanningNoteComments", async (req) => {
        try {
            const items = JSON.parse(req.data.dltCmt);

            // Validate input
            if (!Array.isArray(items) || items.length === 0) {
                return req.reject(400, "No valid data provided for deletion.");
            }

            // Extract unique values for each property
            const LOCATION_IDs = [...new Set(items.map(item => item.LOCATION_ID))];
            const PRODUCT_IDs = [...new Set(items.map(item => item.PRODUCT_ID))];
            const CUSTOMER_GROUPs = [...new Set(items.map(item => item.CUSTOMER_GROUP))];
            const CLASS_NUMs = [...new Set(items.map(item => item.CLASS_NUM))];
            const CHAR_NUMs = [...new Set(items.map(item => item.CHAR_NUM))];
            const CHARVAL_NUMs = [...new Set(items.map(item => item.CHARVAL_NUM))];
            const VERSIONs = [...new Set(items.map(item => item.VERSION))];
            const SCENARIOs = [...new Set(items.map(item => item.SCENARIO))];
            const MODEL_VERSIONs = [...new Set(items.map(item => item.MODEL_VERSION))];
            const WEEK_DATEs = [...new Set(items.map(item => item.WEEK_DATE))];
            const TYPEs = [...new Set(items.map(item => item.TYPE))];

            // Update database safely
            await cds.transaction(req).run(
                UPDATE("CP_OPTION_PERCENTAGE")
                    .with({ COMMENTS: null })
                    .where({
                        LOCATION_ID: { in: LOCATION_IDs },
                        PRODUCT_ID: { in: PRODUCT_IDs },
                        CUSTOMER_GROUP: { in: CUSTOMER_GROUPs },
                        CLASS_NUM: { in: CLASS_NUMs },
                        CHAR_NUM: { in: CHAR_NUMs },
                        CHARVAL_NUM: { in: CHARVAL_NUMs },
                        VERSION: { in: VERSIONs },
                        SCENARIO: { in: SCENARIOs },
                        MODEL_VERSION: { in: MODEL_VERSIONs },
                        WEEK_DATE: { in: WEEK_DATEs },
                        TYPE: { in: TYPEs },
                    })
            );

            return { message: "Comments successfully deleted." };
        } catch (error) {
            console.error("Error during deletePlanningNoteComments:", error);
            return req.reject(500, "An error occurred while deleting comments.");
        }
    });

