    srv.on("generateOptionPercentage", async (req) => {

        //  req.data= {   
        //                 "LOCATION_ID": "1900",
        //                 "PRODUCT_ID": "[\"000000000000002257\"]",
        //                 "FROM_DATE": "2026-07-27",
        //                 "TO_DATE": "2028-07-24",
        //                 "VERSION": "__BASELINE",
        //                 "SCENARIO": "_PLAN",
        //                 "MODEL_VERSION": "Active"
        //             }
        try {
            let { LOCATION_ID: location, PRODUCT_ID: products, FROM_DATE: from, TO_DATE: to, VERSION: version, SCENARIO: scenario, MODEL_VERSION: mv } = req.data;

            // Parse PRODUCT_ID as an array if it's a JSON string
            products = Array.isArray(products) ? products : JSON.parse(products);

            let result = [];
            let tempfrom = await cds.run(`SELECT * from CP_IBPCALENDER_WEEK 
                                                    where WEEK_STARTDATE <= '${from}' 
                                                    and WEEK_ENDDATE >= '${from}'
                                                    and LEVEL = 'W'`);
            let tempto = await cds.run(`SELECT * from CP_IBPCALENDER_WEEK 
                                                    where WEEK_STARTDATE <= '${to}' 
                                                    and WEEK_ENDDATE >= '${to}'
                                                    and LEVEL = 'W'`);
            from = tempfrom.length > 0 ? tempfrom[0].WEEK_STARTDATE : from;
            to = tempto.length > 0 ? tempto[0].WEEK_ENDDATE : to;

            // Fetch option percentage data for each product
            const query = `
                SELECT 
                    LOCATION_ID,
                    PRODUCT_ID,
                    CUSTOMER_GROUP,
                    MODEL_VERSION,
                    CHAR_NUM,
                    CHARVAL_NUM,
                    VERSION,
                    SCENARIO,
                    WEEK_DATE,
                    OPT_PERCENT,
                    OPT_QTY,
                    PROD_DEMAND,
                    ACT_DEM_VC,
                    ACT_DEM,
                    EFFECTIVE_QTY,
                    EFFECTIVE_PER
                FROM V_EFFECTIVE_OPTION_PLAN
                WHERE LOCATION_ID = ? 
                  AND PRODUCT_ID = ?
                  AND WEEK_DATE >= ? 
                  AND WEEK_DATE <= ?
                  AND MODEL_VERSION = ?
                  AND VERSION = ?
                  AND SCENARIO = ?
                ORDER BY LOCATION_ID, PRODUCT_ID, CUSTOMER_GROUP, MODEL_VERSION, CHAR_NUM, CHARVAL_NUM, VERSION, SCENARIO, WEEK_DATE
            `;

            try {
                for (let product of products) {
                    let lsData = await cds.run(query, [location, product, from, to, mv, version, scenario]);
                    result = result.concat(lsData);
                }
            } catch (error) {
                let sError = "Error fetching option percentage data.Reason: " + error.message;
                await GenF.jobSchMessage('', sError, req);
                return;
            }

            if (result.length === 0) {
                await GenF.jobSchMessage('X', "No data found", req);
                return;
            }

            const finalResult = await deleteAndInsert(result);

            if (finalResult === 'Success') {
                await GenF.jobSchMessage('X', "Data saved successfully", req);

                // Prepare locProdData using location and products variables
                const locProdData = products.map(product => ({
                    LOCATION_ID: location,
                    PRODUCT_ID: product,
                    VERSION: version,
                    SCENARIO: scenario,
                    MODEL_VERSION: mv
                }));

                // Call updateOptionQuantities
                const updateReq = {
                    LocProdData: JSON.stringify(locProdData)
                };
                await srv.emit("updateOptionQuantities", updateReq);
            } else {
                await GenF.jobSchMessage('', "Error While Inserting or Deleting Data from CP_IBP_FCHARPLAN Table", req);
            }
        } catch (error) {
            let sError = "Option Percentage Generation failed.Reason: " + error.message;
            await GenF.jobSchMessage('', sError, req);
        }

        async function deleteAndInsert(params) {
            const upsertEntries = params.map(el => ({
                LOCATION_ID: el.LOCATION_ID,
                PRODUCT_ID: el.PRODUCT_ID,
                CLASS_NUM: 'NA',
                CHAR_NUM: el.CHAR_NUM,
                CHARVAL_NUM: el.CHARVAL_NUM,
                VERSION: el.VERSION,
                SCENARIO: el.SCENARIO,
                MODEL_VERSION: el.MODEL_VERSION,
                WEEK_DATE: el.WEEK_DATE,
                OPT_PERCENT: parseFloat(el.OPT_PERCENT).toFixed(2), // Ensure DECIMAL(5,2) format
                OPT_QTY: parseFloat(el.OPT_QTY).toFixed(3),         // Ensure DECIMAL(13,3) format
                MANUALOPTION: parseFloat(el.OPT_PERCENT).toFixed(2) // Ensure DECIMAL(5,2) format
            }));

            // Validate and parse numeric values to ensure compatibility with DECIMAL types
            for (let entry of upsertEntries) {
                entry.OPT_PERCENT = isNaN(entry.OPT_PERCENT) ? 0.00 : parseFloat(entry.OPT_PERCENT);
                entry.OPT_QTY = isNaN(entry.OPT_QTY) ? 0.000 : parseFloat(entry.OPT_QTY);
                entry.MANUALOPTION = isNaN(entry.MANUALOPTION) ? 0.00 : parseFloat(entry.MANUALOPTION);
            }

            let cqnQuery = { UPSERT: { into: { ref: ['CP_IBP_FCHARPLAN'] }, entries: upsertEntries } };
            try {
                await cds.run(cqnQuery);
                return 'Success';
            } catch (exception) {
                await GenF.jobSchMessage('', "Error to update Data", req);
                return 'Error';
            }
        }
    });

