    //function to get Time Series Data
    srv.on("getTimeSeriesData", async (req) => {
        let data = JSON.parse(req.data.TSDATA);
        let skip = req.data.Skip;
        let top = req.data.TopCount;
        console.log("Data", data);
        let results = []
        for (let record of data) {
            let oLocation = record.LOCATION_ID;
            let oProduct = record.PRODUCT_ID;
            let oVersion = record.VERSION;
            let oScenario = record.SCENARIO;
            let oCharnum = record.CHAR_NUM;
            let oWeekDate = record.WEEK_DATE;
            let oCustGrp = record.CUSTOMER_GROUP;
            let Flag = record.FLAG;

            try {
                let query = "";
                if (Flag === "F") {
                    query = `SELECT * FROM V_OBJECTDEPCHARDESC WHERE 1=1`;
                    if (oLocation) query += ` AND "LOCATION_ID" = '${oLocation}'`;
                    if (oProduct) query += ` AND "PRODUCT_ID" = '${oProduct}'`;
                    if (oVersion) query += ` AND "VERSION" = '${oVersion}'`;
                    if (oScenario) query += ` AND "SCENARIO" = '${oScenario}'`;
                }
                else if (Flag === "H") {
                    query = `SELECT * FROM V_TS_HISTORY_WEEKLY WHERE 1=1`;
                    if (oLocation) query += ` AND "LOCATION_ID" = '${oLocation}'`;
                    if (oProduct) query += ` AND "PRODUCT_ID" = '${oProduct}'`;
                    if (oCharnum) query += ` AND "CHAR_NUM" = '${oCharnum}'`;
                    if (oWeekDate) query += ` AND "CAL_DATE" = '${oWeekDate}'`;
                }
                else if (Flag === "HD") {
                    query = `SELECT * FROM V_TS_HISTORY_DAILY WHERE 1=1`;
                    if (oLocation) query += ` AND "LOCATION_ID" = '${oLocation}'`;
                    if (oProduct) query += ` AND "PRODUCT_ID" = '${oProduct}'`;
                    if (oCharnum) query += ` AND "CHAR_NUM" = '${oCharnum}'`;
                    if (oWeekDate) query += ` AND "CAL_DATE" = '${oWeekDate}'`;
                }
                else if (Flag === "HC") {
                    query = `SELECT * FROM V_TS_HISTORY_CUSTOMER_NEW WHERE 1=1`;
                    if (oLocation) query += ` AND "LOCATION_ID" = '${oLocation}'`;
                    if (oProduct) query += ` AND "PRODUCT_ID" = '${oProduct}'`;
                    if (oCharnum) query += ` AND "CHAR_NUM" = '${oCharnum}'`;
                    if (oWeekDate) query += ` AND "CAL_DATE" = '${oWeekDate}'`;
                    if (oCustGrp) query += ` AND "CUSTOMER_GROUP" = '${oCustGrp}'`;
                }

                if (query) {
                    let queryResult = await cds.run(query);
                    if (queryResult.length > 0) {
                        queryResult = queryResult.slice(skip, skip + top);
                        queryResult = JSON.stringify(queryResult);
                        results.push(queryResult);
                    }
                }
            } catch (e) {
                return `Failed to import data for record with FLAG ${Flag}`;
            }
        }

        return results;
    })

