    // Function to save product demand data for the application - Option Percentage
    // Function to save product demand data for the application - Option Percentage
    srv.on("saveProductDemandData", async (req) => {
        const data = JSON.parse(req.data.demData);
        let responseMessage = "Successfully Saved Data";

        try {
            if (data.length === 0) {
                throw new Error("No data provided for processing.");
            }

            // Process each demand data record
            for (const record of data) {
                await processOptionPercentage(record);
            }

            // Upsert data into CP_IBP_FUTUREDEMAND_LOCPRODCUST
            await upsertFutureDemandWithCustomerGroup(data);

            // Aggregate and upsert data into CP_IBP_FUTUREDEMAND
            await aggregateAndUpsertFutureDemand(data, req);

        } catch (error) {
            responseMessage = `Error: ${error.message}`;
            console.error("Error processing demand data:", error);
            throw error;
        }

        return responseMessage;

        /**
         * Processes option percentage data for a given record.
         * @param {Object} record - The demand data record.
         */
        async function processOptionPercentage(record) {
            const query = `
        SELECT 
            LOCATION_ID,
            PRODUCT_ID,
            CUSTOMER_GROUP,
            CLASS_NUM,
            CHAR_NUM,
            CHARVAL_NUM,
            MODEL_VERSION,
            VERSION,
            SCENARIO,
            WEEK_DATE,
            TYPE,
            OPT_PERCENT,
            OPT_QTY
        FROM CP_OPTION_PERCENTAGE
        WHERE LOCATION_ID = ?
            AND PRODUCT_ID = ?
            AND CUSTOMER_GROUP = ?
            AND VERSION = ?
            AND SCENARIO = ?
            AND WEEK_DATE >= ?
            AND WEEK_DATE <= ?
    `;

            const params = [
                record.LOCATION_ID,
                record.PRODUCT_ID,
                record.CUSTOMER_GROUP,
                record.VERSION,
                record.SCENARIO,
                record.WEEK_STARTDATE,
                record.WEEK_ENDDATE
            ];

            const results = await cds.run(query, params);

            if (results.length > 0) {
                const upsertPromises = results.map(result => {
                    const updatedQuantity = (result.OPT_PERCENT / 100) * record.QUANTITY;
                    return cds.run(
                        UPSERT.into("CP_OPTION_PERCENTAGE").entries({
                            ...result,
                            OPT_QTY: updatedQuantity
                        })
                    );
                });
                await Promise.all(upsertPromises);
            }
        }

        /**
         * Upserts demand data into CP_IBP_FUTUREDEMAND_LOCPRODCUST for each week in the date range.
         * @param {Array} demandData - The array of demand data records.
         */
        async function upsertFutureDemandWithCustomerGroup(demandData) {
            const upsertPromises = [];

            for (const record of demandData) {
                // Get all weeks between start and end date from the database
                const weekQuery = `
                SELECT DISTINCT WEEK_DATE 
                FROM CP_IBP_FUTUREDEMAND_LOCPRODCUST 
                WHERE WEEK_DATE >= ? AND WEEK_DATE <= ?
                ORDER BY WEEK_DATE
            `;

                const weekResults = await cds.run(weekQuery, [record.WEEK_STARTDATE, record.WEEK_ENDDATE]);

                // If no existing weeks found, you might need to generate them or handle differently
                if (weekResults.length === 0) {
                    // Option 1: Use start date as single week
                    upsertPromises.push(
                        cds.run(
                            UPSERT.into("CP_IBP_FUTUREDEMAND_LOCPRODCUST").entries({
                                LOCATION_ID: record.LOCATION_ID,
                                PRODUCT_ID: record.PRODUCT_ID,
                                CUSTOMER_GROUP: record.CUSTOMER_GROUP,
                                VERSION: record.VERSION,
                                SCENARIO: record.SCENARIO,
                                WEEK_DATE: record.WEEK_STARTDATE,
                                QUANTITY: parseFloat(record.QUANTITY)
                            })
                        )
                    );
                } else {
                    // Distribute quantity across all weeks in the range
                    const quantityPerWeek = parseFloat(record.QUANTITY) / weekResults.length;

                    weekResults.forEach(weekResult => {
                        upsertPromises.push(
                            cds.run(
                                UPSERT.into("CP_IBP_FUTUREDEMAND_LOCPRODCUST").entries({
                                    LOCATION_ID: record.LOCATION_ID,
                                    PRODUCT_ID: record.PRODUCT_ID,
                                    CUSTOMER_GROUP: record.CUSTOMER_GROUP,
                                    VERSION: record.VERSION,
                                    SCENARIO: record.SCENARIO,
                                    WEEK_DATE: weekResult.WEEK_DATE,
                                    QUANTITY: quantityPerWeek
                                })
                            )
                        );
                    });
                }
            }

            await Promise.all(upsertPromises);
        }

        /**
         * Aggregates and upserts demand data into CP_IBP_FUTUREDEMAND for date range.
         * @param {Array} demandData - The array of demand data records.
         */
        async function aggregateAndUpsertFutureDemand(demandData, req) {
            var iFutureDemand = [], existingData = [];
            if (demandData.length > 0) {
                existingData = await cds.run(`
                SELECT *
                FROM "CP_IBP_FUTUREDEMAND"
                WHERE LOCATION_ID = '${demandData[0].LOCATION_ID}'
                AND VERSION = '${demandData[0].VERSION}'
                AND SCENARIO = '${demandData[0].SCENARIO}'
                AND PRODUCT_ID = ('${demandData[0].PRODUCT_ID}')
              `);
            }
            for (const record of demandData) {
                // Get all weeks that fall within the date range
                const weekQuery = `
                SELECT DISTINCT WEEK_DATE 
                FROM CP_IBP_FUTUREDEMAND_LOCPRODCUST 
                WHERE LOCATION_ID = ?
                    AND PRODUCT_ID = ?
                    AND VERSION = ?
                    AND SCENARIO = ?
                    AND WEEK_DATE >= ?
                    AND WEEK_DATE <= ?
                ORDER BY WEEK_DATE
            `;

                const weekParams = [
                    record.LOCATION_ID,
                    record.PRODUCT_ID,
                    record.VERSION,
                    record.SCENARIO,
                    record.WEEK_STARTDATE,
                    record.WEEK_ENDDATE
                ];

                const weekResults = await cds.run(weekQuery, weekParams);

                // Process each week in the range
                for (const weekResult of weekResults) {
                    const aggregateQuery = `
                    SELECT 
                        LOCATION_ID,
                        PRODUCT_ID,
                        VERSION,
                        SCENARIO,
                        WEEK_DATE,
                        SUM(QUANTITY) as TOTAL_QUANTITY
                    FROM CP_IBP_FUTUREDEMAND_LOCPRODCUST
                    WHERE LOCATION_ID = ?
                        AND PRODUCT_ID = ?
                        AND VERSION = ?
                        AND SCENARIO = ?
                        AND WEEK_DATE = ?
                    GROUP BY
                        LOCATION_ID,
                        PRODUCT_ID,
                        VERSION,
                        SCENARIO,
                        WEEK_DATE
                `;

                    const aggregateParams = [
                        record.LOCATION_ID,
                        record.PRODUCT_ID,
                        record.VERSION,
                        record.SCENARIO,
                        weekResult.WEEK_DATE
                    ];

                    const [aggregatedResult] = await cds.run(aggregateQuery, aggregateParams);

                    if (aggregatedResult) {
                        await cds.run(
                            UPSERT.into("CP_IBP_FUTUREDEMAND").entries({
                                LOCATION_ID: aggregatedResult.LOCATION_ID,
                                PRODUCT_ID: aggregatedResult.PRODUCT_ID,
                                VERSION: aggregatedResult.VERSION,
                                SCENARIO: aggregatedResult.SCENARIO,
                                WEEK_DATE: aggregatedResult.WEEK_DATE,
                                QUANTITY: parseFloat(aggregatedResult.TOTAL_QUANTITY)
                            })
                        );
                        iFutureDemand.push({
                            LOCATION_ID: aggregatedResult.LOCATION_ID,
                            PRODUCT_ID: aggregatedResult.PRODUCT_ID,
                            VERSION: aggregatedResult.VERSION,
                            SCENARIO: aggregatedResult.SCENARIO,
                            WEEK_DATE: aggregatedResult.WEEK_DATE,
                            QUANTITY: parseFloat(aggregatedResult.TOTAL_QUANTITY)
                        })
                    }
                }
            }
            //Alert
            if (existingData.length > 0) {

                const weekDatesArr = await generateAlertLog(iFutureDemand, existingData);
                if (weekDatesArr.length > 0) {
                    const alertLog = [{
                        MSGTXT: [...new Set(weekDatesArr)].sort().join(', '),
                        MSGID: 'S07',
                        APPL: 'VCPLANNER',
                        MSGGRP: 'DATA',
                        LOCATION_ID: demandData[0].LOCATION_ID,
                        PRODUCT_ID: demandData[0].PRODUCT_ID,
                        PARA2: demandData[0].VERSION,
                        PARA3: demandData[0].SCENARIO,
                    }]
                    await GenF.sendAlert('C', alertLog, req);
                }
            }

        }
    });


