    srv.on("getClusters", async (req) => {
        let oInput = (req.data.data) ? JSON.parse(req.data.data) : {};
        var sType = 'ACTUALS';
        if (oInput.TYPE == 'ACTUALS') {
            sType = `SUM(DEMAND) AS ACTUALS`
        }
        else {
            sType = `SUM(${oInput.TYPE}) AS ${oInput.TYPE}`
        }
        //TimePeriod
        var sTimePeriod = '', sOrderGroup = '';
        if (oInput.TIMEPERIOD) {
            sTimePeriod = `${oInput.TIMEPERIOD}` + "(START_DATE) AS " + `${oInput.TIMEPERIOD},`;
            sOrderGroup = `${oInput.TIMEPERIOD}` + "(START_DATE)";
        }

        let query = `
        SELECT LOCATION_ID,PRODUCT_ID,MODEL_PROFILE,CLUSTER_ID,UNIQUE_ID,
        ${sType},`

        if (oInput.TIMEPERIOD) {
            query += sTimePeriod;
        }

        query += `C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, C13, C14, C15,
    C16, C17, C18, C19, C20, C21, C22, C23, C24, C25, C26, C27, C28, C29, C30,
    NC1, NC2, NC3, NC4, NC5, NC6, NC7, NC8, NC9, NC10, NC11, NC12, NC13, NC14, NC15,
    NC16, NC17, NC18, NC19, NC20, NC21, NC22, NC23, NC24, NC25, NC26, NC27, NC28, NC29, NC30
    FROM "CP_V_AHC_CLUSTERS_SORTED_COMBINED" `;
        query += 'WHERE 1=1';

        if (oInput.LOCATION_ID) query += ` AND LOCATION_ID = '${oInput.LOCATION_ID}'`;
        if (oInput.PRODUCT_ID) query += ` AND PRODUCT_ID = '${oInput.PRODUCT_ID}'`;
        if (oInput.CLUSTER_ID) query += ` AND CLUSTER_ID = '${oInput.CLUSTER_ID}'`;
        if (oInput.MODEL_PROFILE) query += ` AND MODEL_PROFILE = '${oInput.MODEL_PROFILE}'`;
        if (oInput.UNIQUE_ID) query += ` AND UNIQUE_ID = '${oInput.UNIQUE_ID}'`;
        if (oInput.START_DATE) query += ` AND START_DATE >= '${oInput.START_DATE}'`;
        if (oInput.END_DATE) query += ` AND END_DATE <= '${oInput.END_DATE}'`;

        query += `GROUP BY LOCATION_ID, PRODUCT_ID, MODEL_PROFILE, CLUSTER_ID,UNIQUE_ID,
    C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, C13, C14, C15,C16, C17, C18, C19, C20, C21, C22, C23, C24, C25, C26, C27, C28, C29, C30,
    NC1, NC2, NC3, NC4, NC5, NC6, NC7, NC8, NC9, NC10, NC11, NC12, NC13, NC14, NC15,NC16, NC17, NC18, NC19, NC20, NC21, NC22, NC23, NC24, NC25, NC26, NC27, NC28, NC29, NC30 `
        if (oInput.TIMEPERIOD) {
            query += `,${sOrderGroup}`
        }

        query += `ORDER BY  LOCATION_ID, PRODUCT_ID, CLUSTER_ID,
    C1, C2, C3, C4, C5, C6, C7, C8, C9, C10, C11, C12, C13, C14, C15,C16, C17, C18, C19, C20, C21, C22, C23, C24, C25, C26, C27, C28, C29, C30,
    NC1, NC2, NC3, NC4, NC5, NC6, NC7, NC8, NC9, NC10, NC11, NC12, NC13, NC14, NC15,NC16, NC17, NC18, NC19, NC20, NC21, NC22, NC23, NC24, NC25, NC26, NC27, NC28, NC29, NC30`
        if (oInput.TIMEPERIOD) {
            query += `,${sOrderGroup}`
        }

        let queryResult = await cds.run(query);
        if (queryResult.length > 0) {
            return JSON.stringify(queryResult);
        }
    })

