    srv.on("generateteleperiods", async (req) => {
        // let data = JSON.parse(req.data.PERIODDATA);
        let data = await cds.run(`SELECT DISTINCT PARAMETER_ID, VALUE FROM CP_PARAMETER_VALUES WHERE PARAMETER_ID IN (22,23,24) order by PARAMETER_ID `)
        let responseMessage = "Successfully inserted";
        let { VALUE: iWeeks } = data[0];
        let { VALUE: iMonths } = data[1];
        let { VALUE: iQrtr } = data[2];
        let TotalData = [];

        let lDate;
        let lDay;

        iWeeks = parseInt(iWeeks);
        iMonths = parseInt(iMonths);
        iQrtr = parseInt(iQrtr) / 3;



        const now = new Date();
        // const calenderData = await cds.run(`select *  FROM CP_DUMMY_IBPCALENDER_WEEK`);
        // const weeklyData = calenderData.filter(el => el.TPLEVEL === 3);
        // const monthlyData = calenderData.filter(el => el.TPLEVEL === 4);
        // const qrtrlyData = calenderData.filter(el => el.TPLEVEL === 5);

        const calenderData = await cds.run(`select *  FROM CP_IBPCALENDER_WEEK`);
        // const weeklyData = calenderData.filter(el => el.TPLEVEL === 'W');
        // const monthlyData = calenderData.filter(el => el.TPLEVEL === 'M');
        // const qrtrlyData = calenderData.filter(el => el.TPLEVEL === 'Q');

        const weeklyData = calenderData.filter(el => el.LEVEL === 'W');
        const monthlyData = calenderData.filter(el => el.LEVEL === 'M');
        const qrtrlyData = calenderData.filter(el => el.LEVEL === 'Q');

        //For Week data
        const currentMonthIndex = monthlyData.findIndex(el => new Date(el.PERIODSTART) <= now && new Date(el.PERIODEND) >= now);
        const weekEnd = monthlyData[currentMonthIndex + iWeeks]?.PERIODEND;
        const currentWeek = weeklyData.find(el => new Date(el.PERIODSTART) <= now && new Date(el.PERIODEND) >= now);
        // const currentWeek = weeklyData.find(el => new Date(el.PERIODSTART) > now);
        const weekStart = currentWeek?.PERIODSTART;
        const weeklyFullData = weeklyData.filter(el => el.PERIODSTART >= weekStart && el.PERIODEND <= weekEnd);

        lDate = new Date(weeklyFullData[0].PERIODSTART);
        lDay = lDate.getDay();
        if (lDay === 1) {
            lDay = 0;
        } else {
            if (lDay !== 0) lDay = 7 - lDay;
            lDay = lDay + 1;
        }

        for (let w = 0; w < weeklyFullData.length; w++) {
            let start = new Date(weeklyFullData[w].PERIODSTART);
            let end = new Date(weeklyFullData[w].PERIODEND);

            let newStart = new Date(start.setDate(start.getDate() + lDay));
            weeklyFullData[w].StartDate = new Date(newStart.getFullYear(), newStart.getMonth(), newStart.getDate()).toISOString().split('T')[0];

            let newEnd = new Date(end.setDate(end.getDate() + lDay));
            weeklyFullData[w].EndDate = new Date(newEnd.getFullYear(), newEnd.getMonth(), newEnd.getDate()).toISOString().split('T')[0];
            weeklyFullData[w].LEVEL = "W";
        }
        TotalData = TotalData.concat(weeklyFullData);

        //For Month Data
        const indexMonth = monthlyData.findIndex(el => el.PERIODEND === weekEnd);
        const monthStart = monthlyData[indexMonth + 1]?.PERIODSTART;
        const monthEnd = monthlyData[indexMonth + iMonths]?.PERIODEND;

        const endMonth = qrtrlyData.find(el => new Date(el.PERIODSTART) <= new Date(monthEnd) && new Date(el.PERIODEND) >= new Date(monthEnd))?.PERIODEND;

        const monthFullData = monthlyData.filter(el => el.PERIODSTART >= monthStart && el.PERIODEND <= endMonth);


        // let monthWeekData = calenderData.filter(el => el.PERIODSTART >= monthStart && el.PERIODEND <= endMonth && el.LEVEL === 'W');

        // for(let m=0; m< monthWeekData.length; m++){
        //     let index = monthFullData.findIndex(e=> new Date(e.PERIODSTART) <= new Date(monthWeekData[m].PERIODSTART) &&
        //                                             new Date(e.PERIODEND) >= new Date(monthWeekData[m].PERIODEND) );
        //     monthWeekData[m].PERIODDESC = monthFullData[index].PERIODDESC;
        // }

        // for (let m = 0; m < monthFullData.length; m++) {

        // let TempData = monthWeekData.filter(el => new Date(el.PERIODSTART) >= new Date(monthFullData[m].PERIODSTART) && new Date(el.PERIODEND) <= new Date(monthFullData[m].PERIODEND));
        if (monthEnd !== undefined) {
            monthFullData.forEach(el => {
                // el.PERIODDESC = monthFullData[m].PERIODDESC;
                el.LEVEL = "M";
                let start = new Date(el.PERIODSTART);
                let end = new Date(el.PERIODEND);

                let newStart = new Date(start.setDate(start.getDate() + lDay));
                el.StartDate = new Date(newStart.getFullYear(), newStart.getMonth(), newStart.getDate()).toISOString().split('T')[0];

                let newEnd = new Date(end.setDate(end.getDate() + lDay));
                el.EndDate = new Date(newEnd.getFullYear(), newEnd.getMonth(), newEnd.getDate()).toISOString().split('T')[0];

            });
            TotalData = TotalData.concat(monthFullData);

            // }
            //For Quarterly Data
            const indexQrtr = qrtrlyData.findIndex(el => el.PERIODEND === endMonth);
            const qrtrFullData = qrtrlyData.slice(indexQrtr + 1, indexQrtr + iQrtr + 1);

            // let QuarterStart = new Date(qrtrFullData[0].PERIODSTART);
            // let QuarterEnd = new Date(qrtrFullData[qrtrFullData.length - 1].PERIODEND);

            // let QuarterWeekData = calenderData.filter(el => new Date(el.PERIODSTART) >= QuarterStart && new Date(el.PERIODEND) <= QuarterEnd && el.LEVEL === 'W');

            // for (let m = 0; m < qrtrFullData.length; m++) {

            //     let TempData = QuarterWeekData.filter(el => new Date(el.PERIODSTART) >= new Date(qrtrFullData[m].PERIODSTART) && new Date(el.PERIODEND) <= new Date(qrtrFullData[m].PERIODEND));
            qrtrFullData.forEach(el => {
                // el.PERIODDESC = qrtrFullData[m].PERIODDESC;
                el.LEVEL = "Q";
                let start = new Date(el.PERIODSTART);
                let end = new Date(el.PERIODEND);

                let newStart = new Date(start.setDate(start.getDate() + lDay));
                el.StartDate = new Date(newStart.getFullYear(), newStart.getMonth(), newStart.getDate()).toISOString().split('T')[0];

                let newEnd = new Date(end.setDate(end.getDate() + lDay));
                el.EndDate = new Date(newEnd.getFullYear(), newEnd.getMonth(), newEnd.getDate()).toISOString().split('T')[0];

            });
            TotalData = TotalData.concat(qrtrFullData);
        }
        // }

        //Merge all data into into a single array to insert into table
        // const  merged = [...weeklyFullData, ...monthFullData, ...qrtrFullData].map(item => ({
        //   PERIODDESC: item.PERIODDESC,
        //   PERIODSTART: item.PERIODSTART,
        //   PERIODEND: item.PERIODEND
        // }));

        const merged = TotalData.map(item => ({
            PERIODDESC: item.PERIODDESC,
            PERIODSTART: item.StartDate,
            PERIODEND: item.EndDate,
            LEVEL: item.LEVEL
        }));
        try {
            await cds.run(`DELETE FROM "CP_TELESCOPIC_PERIODS" `);
            await cds.run(INSERT.into("CP_TELESCOPIC_PERIODS").entries(merged));
            await GenF.jobSchMessage('X', "Successfully updated the Telescopic Periods", req);
        }
        catch (ex) {
            responseMessage = "Failed to insert";
            await GenF.jobSchMessage(' ', `Failed to update the Telescopic Periods.Reason: ${ex.message}`, req);
        }

    })


