    srv.on("getPlannedOrderData", async (req) => {
        let aData = JSON.parse(req.data.CHAR_DATA);
        var aResponse = [];
        if (aData.length > 0) {
            const grouped = aData.reduce((acc, { CHAR_NUM, CHAR_VALUE }) => {
                if (!acc[CHAR_NUM]) acc[CHAR_NUM] = [];
                acc[CHAR_NUM].push(CHAR_VALUE);
                return acc;
            }, {});

            const whereClauses = Object.entries(grouped).map(([num, values]) => {
                const valueList = values.map(v => `'${v}'`).join(', ');
                return `(CHAR_NUM='${num}' AND CHAR_VALUE IN (${valueList}))`;
            });

            let query = `
SELECT DISTINCT UNIQUE_ID
FROM "CV_PLANNED_ORDER_ANALYSIS"
WHERE (${whereClauses.join(' OR ')})
  AND PRODUCT_ID='${req.data.PRODUCT_ID}'
  AND LOCATION_ID='${req.data.LOCATION_ID}'
  AND CONFIGURATION_PRODUCT='${req.data.CONFIG_PROD}'
`;

            // Optional filters
            if (req.data.MODEL_VERSION) {
                query += ` AND MODEL_VERSION='${req.data.MODEL_VERSION}'`;
            }

            if (req.data.START_DATE && req.data.END_DATE) {
                query += ` AND WEEK_DATE BETWEEN '${req.data.START_DATE}' AND '${req.data.END_DATE}'`;
            }
            if (req.data.UNIQUE_ID) {
                query += ` AND UNIQUE_ID IN (${JSON.parse(req.data.UNIQUE_ID).map(id => `'${id}'`).join(', ')})`;
            }
            // Add grouping condition to ensure all CHAR_NUMs exist
            query += `
GROUP BY UNIQUE_ID
HAVING COUNT(DISTINCT CHAR_NUM) = ${Object.keys(grouped).length};
`;

            aResponse1 = await cds.run(query);
            if (aResponse1.length > 0) {
                const uniqueIds = aResponse1.map(row => `'${row.UNIQUE_ID}'`).join(', ');

                // Build 2nd query to fetch all fields for those IDs
                let query2 = `
            SELECT *
            FROM "CV_PLANNED_ORDER_ANALYSIS"
            WHERE UNIQUE_ID IN (${uniqueIds})
              AND CHAR_NUM IN (${Object.keys(grouped).map(v => `'${v}'`).join(', ')})
              AND CHAR_VALUE IN (${Object.values(grouped).flat().map(v => `'${v}'`).join(', ')})
        `;

                if (req.data.START_DATE && req.data.END_DATE) {
                    query2 += ` AND WEEK_DATE BETWEEN '${req.data.START_DATE}' AND '${req.data.END_DATE}'`;
                }

                // Execute second query
                aResponse = await cds.run(query2);
            }
        }
        return JSON.stringify(aResponse);
    })
