    srv.on("getClusterFilter", async (req) => {
        try {
            const filter = req.data;
            const yearArray = JSON.parse(filter.year);
            //             const query = `
            //     SELECT DISTINCT CLUSTER_ID, PRIMARY_ID, CHAR_DESC,CHAR_SEQUENCE
            //     FROM "CV_CLUSTER_HEATMAP05"
            //       (
            //         placeholder."$$LOCATION$$" => '${filter.loc}',
            //         placeholder."$$CONFIG_PROD$$" => '${filter.cProd}',
            //         placeholder."$$PRODUCT$$" => '${filter.prod}'
            //       )
            //           WHERE YEAR = '${yearArray[0]}'
            //   `;
            let sStart = yearArray[0] + '-01-01', sEnd = yearArray[0] + '-12-31';
            const query = `   SELECT DISTINCT CL.CLUSTER_ID,CL.UNIQUE_ID AS "PRIMARY_ID",V_UNIQUE_ID_ITEM.CHAR_DESC,SEQUENCE AS "CHAR_SEQUENCE"
    FROM
    "CP_CLUSTERS_UID_SEQUENCE" AS CL
    INNER JOIN "V_UNIQUE_ID_ITEM" ON
    V_UNIQUE_ID_ITEM.UNIQUE_ID = CL.UNIQUE_ID
    INNER JOIN V_CHARGROUPWEIGHTAGE AS CG
    ON CG.PRODUCT_ID = CL.PRODUCT_ID
    AND CG.CHAR_NUM = V_UNIQUE_ID_ITEM.CHAR_NUM
    INNER JOIN "V_SALES_H" AS SALES ON SALES.PRIMARY_ID = CL.UNIQUE_ID
    AND V_UNIQUE_ID_ITEM.UID_TYPE='P' AND SALES.SALES_DOC NOT LIKE '%SE%'
    WHERE CL.LOCATION_ID='${filter.loc}' AND CL.PRODUCT_ID='${filter.cProd}'
    AND SALES.MAT_AVAILDATE >='${sStart}' AND SALES.MAT_AVAILDATE <='${sEnd}'`
            const Data = await cds.run(query);
            // console.log("Data length:", Data.length);
            return JSON.stringify(Data);
        } catch (e) {
            console.error(e);
            req.error(500, 'Error fetching cluster filter data');
        }
    })

