    srv.on("getClusterHeatmapFun", async (req) => {
        try {
            const { loc, cProd, prod, year, clusterId, charDesc, primaryId } = req.data;


            let whereConditions = [];

            // Only add WHERE condition if parameter exists AND is not an empty array
            if (year && year.length > 0) {
                try {
                    const yearArray = JSON.parse(year);
                    if (yearArray.length > 0) {
                        const yearList = yearArray.map(y => `'${y}'`).join(',');
                        whereConditions.push(`YEAR IN (${yearList})`);
                    }
                } catch (parseError) {
                    console.error("Error parsing year:", parseError);
                }
            }

            if (clusterId && clusterId.length > 0) {
                try {
                    const clusterArray = JSON.parse(clusterId);
                    if (clusterArray.length > 0) {
                        const clusterList = clusterArray.join(',');
                        whereConditions.push(`CLUSTER_ID IN (${clusterList})`);
                    }
                } catch (parseError) {
                    console.error("Error parsing clusterId:", parseError);
                }
            }

            if (charDesc && charDesc.length > 0) {
                try {
                    const charDescArray = JSON.parse(charDesc);
                    if (charDescArray.length > 0) {
                        const charDescList = charDescArray.map(c => `'${c}'`).join(',');
                        whereConditions.push(`CHAR_DESC IN (${charDescList})`);
                    }
                } catch (parseError) {
                    console.error("Error parsing charDesc:", parseError);
                }
            }

            if (primaryId && primaryId.length > 0) {
                try {
                    const primaryIdArray = JSON.parse(primaryId);
                    if (primaryIdArray.length > 0) {
                        const primaryIdList = primaryIdArray.join(',');
                        whereConditions.push(`PRIMARY_ID IN (${primaryIdList})`);
                    }
                } catch (parseError) {
                    console.error("Error parsing primaryId:", parseError);
                }
            }

            const whereClause = whereConditions.length > 0 ? `WHERE ${whereConditions.join(' AND ')}` : '';

            const query = `
            SELECT "CLUSTER_ID",
                   "CLUSTER_SORT_SEQ",
                   "PRIMARY_ID_SEQUENCE",
                   "PRIMARY_ID",
                   "CHAR_NUM",
                   "CHAR_DESC",
                   "CHARVAL_NUM",
                   "CHAR_SEQUENCE",
                   "COLOR_CODE",
                   "YEAR",
                   "UNIQUE_ID_COLOR",
                   "ORD_QTY"
            FROM "CV_CLUSTER_HEATMAP05"
            (
                placeholder."$$LOCATION$$" => '${loc}',
                placeholder."$$CONFIG_PROD$$" => '${cProd}',
                placeholder."$$PRODUCT$$" => '${prod}'
            )
            ${whereClause}
        `;

            const Data = await cds.run(query);
            return JSON.stringify(Data);
        } catch (e) {
            console.error("Full error:", e);
            console.error("Error stack:", e.stack);
            req.error(500, `Error fetching cluster heatmap data: ${e.message}`);
        }
    });
