    //Below function is for Importing roles
    srv.on("importRoles", async (req) => {
        let aRoles = JSON.parse(req.data.ROLES);
        const sUser = req.data.USER;
        var sResponse = '';
        if (aRoles.length > 0) {
            let aCreatedRoles = await cds.run(`SELECT DISTINCT ROLE_NAME,DESCRIPTION FROM "CP_ROLES"`);
            if (aCreatedRoles.length == 0) {
                return sResponse = 'No Roles exists,Please create Roles!'
            }
            let oCreatedRoles = {}, aInvalid = [], aValid = [];
            for (var r = 0; r < aCreatedRoles.length; r++) {
                let el = aCreatedRoles[r];
                oCreatedRoles[el.ROLE_NAME] ??= []
                oCreatedRoles[el.ROLE_NAME] = el.DESCRIPTION;
            }
            for (var i = 0; i < aRoles.length; i++) {
                let el = aRoles[i];
                if (oCreatedRoles[el.Name] != null && oCreatedRoles[el.Name] != undefined) {
                    aValid.push({
                        "USER": sUser,
                        "ROLE_NAME": el.Name,
                        "DESCRIPTION": oCreatedRoles[el.Name],
                    })
                }
                else {
                    aInvalid.push(el.Name);
                }
            }
            if (aInvalid.length > 0) {
                return sResponse = `The following Role(s) does not exists: ${aInvalid.toString()}`;
            }
            else {
                await cds.run(UPSERT.into("CP_USER_ROLES").entries(aValid));
            }
            return sResponse = 'Roles Assignment is Successfull';
        }
        else {
            return sResponse = 'Please upload valid file';
        }
    })
