    srv.on("maintainProdOrdConsumption", async (req) => {
        const res = req._.res;

        try {
            const data = JSON.parse(req.data.PRDORDDATA);

            const keyMappings = {
                PRODUCTION_CON: item => ({
                    LOCATION_ID: item.LOCATION_ID,
                    SALES_DOC: item.SALES_DOCUMENT?.toString().padStart(10, "0"),
                    SALESDOC_ITEM: item.SALES_DOCUMENT_ITEM?.toString().padStart(10, "0"),
                    REF_PRODID: item.CONFIG_MAT,
                    COMPONENT: item.COMPONENT,
                    COMP_LOC: item.COMP_LOC,
                    MAT_PARENT: item.PARENT_MAT || "",
                    PARENT_LOC: item.PARENT_LOC || "",
                    COMP_PROCURE_TYPE: item.COMP_PROCURE_TYPE || "",
                    COMP_QTY: item.QUANTITY,
                    WEEK_DATE: item.PROD_AVAILABILITY_DT || null
                }),

                SALES_PRODUCTION_ORDER: item => ({
                    SALES_DOC: item.SALES_DOCUMENT?.toString().padStart(10, "0"),
                    SALESDOC_ITEM: item.SALES_DOCUMENT_ITEM?.toString().padStart(10, "0"),
                    PROD_ORDER: item.AUFNR || "",
                    MAT_PARENT: item.PARENT_MAT || "",
                    COMP_QTY: item.QUANTITY,
                    ORD_TYPE: item.ORDER_TYPE || ""
                })
            };

            const entityMap = {
                PRODUCTION_CON: "CP_PROD_ORD_CONSUMPTION",
                SALES_PRODUCTION_ORDER: "CP_SALES_PROD_ORD"
            };

            const key = Object.keys(data)[0];
            const items = data[key];
            const mapper = keyMappings[key];

            console.log(key, items?.length);

            if (!mapper || !Array.isArray(items)) {
                res.status(400).send({ message: "Invalid payload structure" });
                return;
            }

            const entries = items
                .filter(item => Object.keys(item).length > 0)
                .map(mapper);

            if (entries.length === 0) {
                res.status(204).send();
                return;
            }

            const entity = entityMap[key] || ("CP_" + key);

            await cds.run(
                UPSERT.into(entity).entries(entries)
            );



            res.status(200).send({
                message: `Successfully processed ${entries.length} record(s)`
            });

        } catch (err) {
            console.error(err);
            res.status(500).send({
                message: "Internal server error while processing data"
            });
        }
    });


    srv.after('READ', 'getVariantHeader', async (data, req) => {

        // Read user and application info from request headers
        const user = req.headers['x-user-id'];
        const app = req.headers['x-app-name'];

        // If user or app is missing, return empty result
        if (!user || !app) {
            req.results = [];
            return;
        }

        // Filter variants by application name
        const filteredData = data.filter(v => v.APPLICATION_NAME === app);

        // If no variants match the application, return empty result
        if (filteredData.length === 0) {
            req.results = [];
            return;
        }

        // Fetch user access details from authorization view
        const userAccess = await cds.run(`
        SELECT DISTINCT
            FACTORY_LOC,
            PLAN_LOC,
            DEMAND_LOC,
            REF_PRODID,
            PRODUCT_ID
        FROM "V_ROLES_LOCPROD"
        WHERE "USER" = '${user}'
    `);

        // Sets to store user access permissions
        const manufacturingLocationAccessSet = new Set();  // Manufacturing locations
        const demandLocationAccessSet = new Set();         // Demand locations
        const configProductAccessSet = new Set();          // Allowed config products
        const partialProductAccessSet = new Set();         // Allowed partial products
        // const locConfigProdAccessSet = new Set();
        // const locPartialProdAccessSet = new Set();

        // Populate access sets from authorization data
        userAccess.forEach(r => {
            // Collect location access by type
            if (r.FACTORY_LOC) manufacturingLocationAccessSet.add(r.FACTORY_LOC);
            if (r.DEMAND_LOC) demandLocationAccessSet.add(r.DEMAND_LOC);

            // Collect config product access
            if (r.REF_PRODID) {
                configProductAccessSet.add(r.REF_PRODID);
                // if (r.FACTORY_LOC) locConfigProdAccessSet.add(`${r.FACTORY_LOC}|${r.REF_PRODID}`);
                // if (r.PLAN_LOC) locConfigProdAccessSet.add(`${r.PLAN_LOC}|${r.REF_PRODID}`);
                // if (r.DEMAND_LOC) locConfigProdAccessSet.add(`${r.DEMAND_LOC}|${r.REF_PRODID}`);
            }

            // Collect partial product access
            if (r.PRODUCT_ID) {
                partialProductAccessSet.add(r.PRODUCT_ID);

                // if (r.FACTORY_LOC) locPartialProdAccessSet.add(`${r.FACTORY_LOC}|${r.PRODUCT_ID}`);
                // if (r.PLAN_LOC) locPartialProdAccessSet.add(`${r.PLAN_LOC}|${r.PRODUCT_ID}`);
                // if (r.DEMAND_LOC) locPartialProdAccessSet.add(`${r.DEMAND_LOC}|${r.PRODUCT_ID}`);
            }
        });

        // Extract variant IDs from filtered headers
        const variantIds = filteredData.map(v => v.VARIANTID);

        // Fetch all variant items for the selected variants
        const variantItems = await cds.run(`
        SELECT *
        FROM "CP_CREATEVARIANT"
        WHERE VARIANTID IN (${variantIds.join(',')})
    `);

        // Group variant items by VARIANTID
        const itemsByVariant = variantItems.reduce((acc, item) => {
            if (!acc[item.VARIANTID]) acc[item.VARIANTID] = [];
            acc[item.VARIANTID].push(item);
            return acc;
        }, {});

        // Authorization check for a single variant
        const isVariantAuthorized = (items) => {

            // Sets to capture variant-specific filters
            const manufacturingLocations = new Set();
            const demandLocations = new Set();
            const configProducts = new Set();
            const partialProducts = new Set();

            // Extract locations and products used in the variant
            for (const item of items) {

                // Location-related fields
                if (item.FIELD === 'Manufacturing Location') {
                    manufacturingLocations.add(item.VALUE);
                }
                if (item.FIELD === 'Demand Location') {
                    demandLocations.add(item.VALUE);
                }

                // Config product fields
                if (item.FIELD === 'Config Product' || item.FIELD === 'Config Products') {
                    configProducts.add(item.VALUE);
                }

                // Partial / normal product fields
                if (item.FIELD === 'Partial Product' || item.FIELD === 'Products' || item.FIELD === 'Product' || item.FIELD === 'Partial Products') {
                    partialProducts.add(item.VALUE);
                }
            }

            // Check presence of filters
            const hasManufacturingLocation = manufacturingLocations.size > 0;
            const hasDemandLocation = demandLocations.size > 0;
            const hasConfig = configProducts.size > 0;
            const hasPartial = partialProducts.size > 0;

            // If no authorization-relevant fields exist, deny access
            if (!hasManufacturingLocation && !hasDemandLocation && !hasConfig && !hasPartial) {
                return false;
            }

            // Location-based authorization
            if (hasManufacturingLocation) {
                for (const loc of manufacturingLocations) {
                    if (!manufacturingLocationAccessSet.has(loc)) return false;
                }
                return true;
            }

            if (hasDemandLocation) {
                for (const loc of demandLocations) {
                    if (!demandLocationAccessSet.has(loc)) return false;
                }
                return true;
            }

            // Config product-based authorization
            if (hasConfig) {
                for (const prod of configProducts) {
                    if (!configProductAccessSet.has(prod)) return false;
                }
                return true;
            }

            // Partial product-based authorization
            if (hasPartial) {
                for (const prod of partialProducts) {
                    if (!partialProductAccessSet.has(prod)) return false;
                }
                return true;
            }

            // if (!hasLocation && hasConfig && hasPartial) {
            //     for (const prod of configProducts) {
            //         if (!configProductAccessSet.has(prod)) return false;
            //     }
            //     for (const prod of partialProducts) {
            //         if (!partialProductAccessSet.has(prod)) return false;
            //     }
            //     return true;
            // }

            // if (hasLocation && hasConfig) {

            //     for (const loc of locations) {
            //         for (const prod of configProducts) {
            //             if (!locConfigProdAccessSet.has(`${loc}|${prod}`)) {
            //                 return false;
            //             }
            //         }
            //     }

            //     if (hasPartial) {
            //         for (const loc of locations) {
            //             for (const prod of partialProducts) {
            //                 if (!locPartialProdAccessSet.has(`${loc}|${prod}`)) {
            //                     return false;
            //                 }
            //             }
            //         }
            //     }

            //     return true;
            // }

            // if (hasLocation && hasPartial) {

            //     for (const loc of locations) {
            //         for (const prod of partialProducts) {
            //             if (!locPartialProdAccessSet.has(`${loc}|${prod}`)) {
            //                 return false;
            //             }
            //         }
            //     }

            //     return true;
            // }

            // Default deny
            return false;
        };

        // Final filtering of variants based on scope and authorization
        req.results = filteredData.filter(v => {

            const items = itemsByVariant[v.VARIANTID] || [];

            // Private variants: only owner can see, plus authorization check
            if (v.SCOPE === 'Private') {
                return v.USER === user && isVariantAuthorized(items);
            }

            // Public or Global variants: authorization check only
            if (v.SCOPE === 'Public' || v.SCOPE === 'Global') {
                return isVariantAuthorized(items);
            }

            // Any other scope is not allowed
            return false;
        });
    });

