    srv.on('approveProductData', async (req) => {

        try {
            const data = JSON.parse(req.data.PRODUCTDATA);

            for (const key in data) {
                const items = data[key];
                if (!Array.isArray(items) || items.length === 0) continue;

                const aEntries = []
                if (key === 'PARTIALPRODUCT') {
                    const { PRODUCT_ID, LOCATION_ID, REF_PRODID, PROD_TYPE, PROD_DESC, ITEMS, LOC_PROD } = items[0];

                    const header = {
                        PRODUCT_ID,
                        LOCATION_ID,
                        PROD_TYPE,
                        PROD_DESC,
                        REF_PRODID,
                        CONFIGPROD_CHK: null,
                        MANUAL: ""
                    };

                    await cds.run(
                        UPSERT.into('CP_PARTIALPROD_INTRO').entries(header)
                    );

                    if (Array.isArray(ITEMS) && ITEMS.length > 0) {
                        let prodCharVal = await cds.run(`
                    SELECT *
                    FROM "CP_PRODUCT_CHAR_VAL"
                    WHERE PRODUCT_ID = '${REF_PRODID}'`);
                        const charMap = new Map();
                        for (const row of prodCharVal) {
                            charMap.set(`${row.CHAR_NUM}_${row.CHAR_VALUE}`, true);
                        }
                        for (const item of ITEMS) {
                            if (!item.CHARACTERSTIC_NUM || !item.CHARACTERISTIC_VALUE) continue;
                            item.CHARACTERSTIC_NUM = item.CHARACTERSTIC_NUM?.toString().padStart(10, '0')
                            const key = `${item.CHARACTERSTIC_NUM}_${item.CHARACTERISTIC_VALUE}`;
                            const match = charMap.get(key);

                            if (match) {
                                aEntries.push({
                                    PRODUCT_ID,
                                    LOCATION_ID,
                                    CLASS_NUM: item.CLASS_NUM?.toString().padStart(10, '0'),
                                    CHAR_NUM: item.CHARACTERSTIC_NUM,
                                    CHARVAL_NUM: item.CHARACTERISTIC_VALUE,
                                    CHAR_VALUE: item.CHARACTERISTIC_VALUE
                                });
                            }
                        }

                        if (aEntries.length) {
                            await cds.run(
                                UPSERT.into('CP_PARTIALPROD_CHAR_MASTER').entries(aEntries)
                            );
                        }
                    }

                    if (Array.isArray(LOC_PROD) && LOC_PROD.length > 0) {
                        const locProdEntries = LOC_PROD.filter(o => Object.keys(o).length).map(o => ({
                            LOCATION_ID: o.LOCATION_ID,
                            PRODUCT_ID: o.PRODUCT_ID,
                            LOTSIZE_KEY: o.LOTSIZE_KEY,
                            LOT_SIZE: o.LOTSIZE,
                            PROCUREMENT_TYPE: o.PROCUREMENT_TYPE,
                            PLANNING_STRATEGY: o.PLANNING_STRATEGY,
                            MRP_GROUP: o.MRP_GROUP,
                            MRP_TYPE: o.MRP_TYPE,
                            MANUAL: ""
                        }));
                        if (locProdEntries.length) {
                            await cds.run(
                                UPSERT.into('CP_LOCATION_PRODUCT').entries(locProdEntries)
                            );
                        }
                    }

                    await oMVCharfn.processPartialProd();
                    const objSOFn = new SOFunctions();

                    await objSOFn.genPartialProd();

                    continue;
                }


                const entries = items.filter(i => i && Object.keys(i).length);
                if (!entries.length) continue;

                const entity = `CP_${key}`;

                await cds.run(
                    UPSERT.into(entity).entries(entries)
                );
                if (key === "BOM_MAT") {

                    function buildParentLookup(bomData) {
                        const parentLookup = new Map();

                        bomData.forEach(record => {
                            parentLookup.set(record.MAT_CHILD, record);
                        });

                        return parentLookup;
                    }
                    function findTopParentRecord(childRecord, parentLookup) {
                        let currentRecord = parentLookup.get(childRecord.MAT_PARENT);
                        if (!currentRecord) {
                            currentRecord = {
                                LOCATION_ID: childRecord?.LOCATION_ID,
                                MAT_PARENT: childRecord?.MAT_PARENT,
                            }
                        }

                        while (currentRecord && parentLookup.has(currentRecord.MAT_PARENT)) {
                            currentRecord = parentLookup.get(currentRecord.MAT_PARENT);
                        }

                        return currentRecord;
                    }

                    const BOM = await cds.run(`SELECT "LOCATION_ID", "MAT_PARENT", "MAT_CHILD", "COUNTER", "CHILD_LOC", "VALID_FROM", "VALID_TO", "COMP_TYPE", "PHANTOM_IND", "CONFIGURABLE", "CLASS_FLG", "PROD_DESC", "COMPONENT_QTY", "CRITICAL_ASM" FROM "CP_BOM_MAT" `);

                    const parentLookup = buildParentLookup(BOM);
                    const topParentRecord = findTopParentRecord(aEntries[0], parentLookup);

                    const alertLog = [
                        {
                            MSGID: 'S01',
                            APPL: 'VCPLANNER',
                            LOCATION_ID: topParentRecord?.LOCATION_ID || "*",
                            PRODUCT_ID: topParentRecord?.MAT_PARENT || "*",
                            MSGGRP: 'INTERFACE'
                        }
                    ];

                    await GenF.sendAlert('C', alertLog, req);

                }
                else if (key === "CLASS") {
                    const alertLog = [
                        {
                            MSGID: 'S02',
                            APPL: 'VCPLANNER',
                            LOCATION_ID: "*",
                            PRODUCT_ID: "*",
                            MSGGRP: 'INTERFACE'
                        }
                    ];

                    await GenF.sendAlert('C', alertLog, req);

                }
                else if (key == 'CHARACTERISTICS_MASTER' || key == 'CHAR_VALUES_MASTER') {
                    await oMVCharfn.processCharandValues();
                } else if (key == "PRODUCT") {
                    const objSOFn = new SOFunctions();
                    await objSOFn.genPartialProd();
                }
            }

            req.reply({
                StatusCode: 200,
                Status: "Data inserted successfully!"

            });

        } catch (error) {
            console.error("approveProductData service failed:", error);
            req.reply({
                StatusCode: 400,
                Status: error.message || error
            });
        }
    });

    srv.on('getUniqueIdWithCharVal', async (req) => {
        let products = JSON.parse(req.data.PRODUCT_ID).map(item => `'${item}'`);
        let data = JSON.parse(req.data.data);
        let uID = [];
        try {
            const conditions = data.map(({ CharName, CharVal }) => {
                const orConditions = CharVal
                    .map(val => `CONCAT(CHAR_NAME, CHAR_VALUE) = '${CharName}${val}'`)
                    .join(" OR ");

                return `(${orConditions})`;
            });

            const whereClause = conditions.join(" OR ");

            const query = `SELECT UNIQUE_ID,
                            count(unique_id) as COUNTUID
                            FROM V_FORECASTUIDFILTER
                            WHERE PRODUCT_ID IN (${products})
                                AND ${whereClause}
                                group by unique_id
                                order by count(unique_id) desc;`

            const res = await cds.run(query);

            const filterData = res.filter(o => o.COUNTUID === data.length);  //data.length is number of unique Char

            uID = filterData.map(o => o.UNIQUE_ID);

        } catch (error) {
            console.log('Error in getUniqueIdWithCharVal:', error.message);
        }
        return JSON.stringify(uID);
    });

