async function createProjectDetails(req) {
    let aData = [], Flag;
    let aCharVal = [], aCharValDim = [];
    let oCharVal = {}, oCharValDim = {};
    let bSuccess = false;
    let sMessage = '';

    if (req.data.NEWPROJDET) {
        aData = JSON.parse(req.data.NEWPROJDET);
        Flag = req.data.FLAG;
    }
    if (Flag === "X") {
        for (var i = 0; i < aData.length; i++) {
            try {
                await UPDATE`CP_NPI_MAINTAINPROJDET`
                    .with({
                        PROJECT_DET: aData[i].PROJECT_DET,
                        CHANGED_BY: aData[i].USER,
                        CHANGED_DATE: aData[i].CHANGED_DATE
                    })
                    .where(`PROJECT_ID = '${aData[i].PROJECT_ID}'`);

                bSuccess = true;
            } catch (e) {
                GenF.log(e);
                bSuccess = false;
                break;
            }

        }
        if (bSuccess === false) {
            sMessage = 'Failed to update Project Details';
        } else {
            sMessage = 'Successfully updated Project Details';
        }
    }
    else if (Flag === "C") {
        oCharVal.CREATED_BY = aData[0].USER;
        oCharVal.CREATED_DATE = aData[0].CREATED_DATE;
        oCharVal.CHANGED_BY = null;
        oCharVal.CHANGED_DATE = null;
        oCharVal.PROJECT_ID = aData[0].PROJECT_ID;
        oCharVal.PROJECT_DET = aData[0].PROJECT_DET;
        oCharVal.PROJ_STATUS = aData[0].PROJ_STATUS;
        oCharVal.RELEASE_DATE = aData[0].RELEASE_DATE;
        aCharVal.push(oCharVal);
        // Insert Project Details
        if (aCharVal.length > 0) {
            try {
                await cds.run(INSERT.into("CP_NPI_MAINTAINPROJDET").entries(aCharVal));
                bSuccess = true;
            } catch (e) {
                GenF.log(e);
            }

        } else {
            bSuccess = false;
        }
        if (bSuccess === false) {
            sMessage = 'Failed to create Project.';
        } else {
            sMessage = 'Successfully created Project Details.';
        }
    }
    else if (Flag === "U") {
        try {
            await UPDATE`CP_NPI_MAINTAINPROJDET`
                .with({
                    PROJ_STATUS: aData[0].PROJECT_STATUS,
                    RELEASE_DATE: aData[0].RELEASE_DATE,
                    CHANGED_BY: aData[0].USER,
                    CHANGED_DATE: aData[0].CHANGED_DATE
                })
                .where(`PROJECT_ID = '${aData[0].PROJECT_ID}'`);

            bSuccess = true;
        } catch (e) {
            GenF.log(e);
            bSuccess = false;
        }
        if (bSuccess === false) {
            sMessage = 'Failed to update Project Details.';
        } else {
            sMessage = 'Successfully updated Project Details.';
        }
    }
    else if (Flag === "D") {
        try {
            await cds.run(`DELETE FROM "CP_NPI_MAINTAINPROJDET" WHERE "PROJECT_ID" = '` +
                aData[0].PROJECT_ID +
                `'`);

            await cds.run(`DELETE FROM "CP_NPI_CHARVAL" WHERE "PROJECT_ID" = '` +
                aData[0].PROJECT_ID +
                `'`);

            await cds.run(`DELETE FROM "CP_NPI_CHARVAL_DIMENSION" WHERE "PROJECT_ID" = '` +
                aData[0].PROJECT_ID +
                `'`);

            await cds.run(`DELETE FROM "CP_NPI_PHASEOUTDATA" WHERE "PROJECT_ID" = '` +
                aData[0].PROJECT_ID +
                `'`);

            await cds.run(`DELETE FROM "CP_TMP_UNIQUE_ID_HEADER" WHERE "PROJECT_ID" = '` +
                aData[0].PROJECT_ID +
                `'`);
            bSuccess = true;
        } catch (e) {
            GenF.log(e);
            bSuccess = false;
        }
        if (bSuccess === false) {
            sMessage = 'Failed to delete Project Details.';
        } else {
            sMessage = 'Successfully deleted Project Details.';
        }
    }

    return sMessage;
}

async function getTreeData(a, b) {
    let newData = [];
    let Product = a;
    let uid = b;
    let uniqueIds = [];
    let finalData = [];
    let object = {};
    newData = await cds.run(`SELECT DISTINCT A.CHAR_NAME,A.CHAR_DESC,A.CHAR_NUM,A.CHAR_VALUE,CASE
                                WHEN ( B."CHARVAL_DESC" != 'NULL' ) THEN B.CHARVAL_DESC
                                ELSE
                                A.CHAR_VALUE END AS CHARVAL_DESC FROM "V_UNIQUE_ID_ITEMS" as A  LEFT OUTER JOIN V_CHARVAL as B on A.CHAR_NUM = B.CHAR_NUM and A.CHAR_VALUE = B.CHAR_VALUE  WHERE A.PRODUCT_ID='${Product}' AND A.UID_TYPE='${uid}'`);
    for (var i = 0; i < newData.length; i++) {
        uniqueIds = await cds.run(`SELECT UNIQUE_ID, UNIQUE_DESC FROM "V_UNIQUE_ID_ITEMS"
            WHERE "PRODUCT_ID" = '` + Product + `'
            AND "CHAR_NUM"= '` + newData[i].CHAR_NUM + `'
            AND "CHAR_VALUE" = '` + newData[i].CHAR_VALUE + `'
            AND "UID_TYPE"  = '`+ uid + `'`);
        object.CHAR_NUM = newData[i].CHAR_NUM;
        object.CHAR_VALUE = newData[i].CHAR_VALUE;
        object.CHARVAL_DESC = newData[i].CHARVAL_DESC;
        object.CHAR_DESC = newData[i].CHAR_DESC;
        object.CHAR_NAME = newData[i].CHAR_NAME;
        object.UIDS = uniqueIds;
        finalData.push(object);
        object = {};
    }
    return finalData;
}
