async function updateCharType(aData, obj, aVarCharData) {
    let newData = [];
    let vResponse = '';
    let clssNum = aData.CLASS_NUM;
    var aNewPrChar = [], iNextSequence = 0;
    //getting char_num for classes
    newData = await cds.run(`SELECT DISTINCT "PRODUCT_ID","CHAR_NUM" FROM "V_PRODCLSCHARVAL" WHERE "CLASS_NUM" ='${clssNum}' AND "PRODUCT_ID" = '${aData.PRODUCT_ID}' ORDER BY "CHAR_NUM"`);
    iNextSequence = aVarCharData.findLast(c => c.PRODUCT_ID == aData.PRODUCT_ID && c.CHAR_TYPE == 'P')?.SEQUENCE + 1 || 1;
    if (newData?.length > 0) {
        for (let i = 0; i < newData.length; i++) {
            let el = newData[i];
            let key = el.PRODUCT_ID + "_" + el.CHAR_NUM;
            if (!obj[key]) { //If combination doesn't exists, insert into array aNewPrChar                
                aNewPrChar.push({
                    "PRODUCT_ID": el.PRODUCT_ID,
                    "CHAR_NUM": el.CHAR_NUM,
                    "CHAR_TYPE": 'P',
                    "SEQUENCE": iNextSequence
                })
                iNextSequence++;
            }
            else {
                aVarCharData.forEach(item => {// else changing char_type to P along with new sequence number
                    if (item.CHAR_NUM === el.CHAR_NUM) {
                        item.CHAR_TYPE = 'P';
                        item.SEQUENCE = iNextSequence;
                        iNextSequence++;
                    }
                })
            }
        }
    }
    //Concat and sort aVarCharData
    var newaVarCharData = aVarCharData.concat(aNewPrChar);
    newaVarCharData.sort((a, b) => a.CHAR_TYPE.localeCompare(b.CHAR_TYPE));
    //Getting new sequence numbers for CHAR_TYPE='S'
    iNextSequence = newaVarCharData.filter(item => item.CHAR_TYPE === "P") // Filter by CHAR_TYPE = "P"
        .map(item => item.SEQUENCE) // Extract SEQUENCE numbers
        .reduce((max, current) => Math.max(max, current), 0) + 1;
    //Inserting new sequence numbers & sorting array as per Sequence number
    newaVarCharData.forEach(item => {
        if (item.CHAR_TYPE === 'S') {
            item.SEQUENCE = iNextSequence;
            iNextSequence++;
        }
    })
    newaVarCharData.sort((a, b) => a.SEQUENCE - b.SEQUENCE);
    if (newaVarCharData.length > 0) {
        try {
            //Delete the entries for PRODUCT and insert with new CHAR_TYPES and SEQUENCE numbers
            await cds.run(`DELETE FROM "CP_VARCHAR_PS"  WHERE "PRODUCT_ID" = '${aData.PRODUCT_ID}'`);
            await cds.run(INSERT.into("CP_VARCHAR_PS").entries(newaVarCharData));
            vResponse = 'S';
        }
        catch (e) {
            console.log(e);
            vResponse = 'X'
        }
    }
    return vResponse;
}

async function generateAlertLog(generatedData, existingData) {
    let weekArr = []

    const existingMap = new Map();
    existingData.forEach(item => {
        const key = `${item.LOCATION_ID}|${item.PRODUCT_ID}|${item.VERSION}|${item.SCENARIO}|${item.WEEK_DATE}`;
        existingMap.set(key, item.QUANTITY);
    });

    for (const item of generatedData) {
        const key = `${item.LOCATION_ID}|${item.PRODUCT_ID}|${item.VERSION}|${item.SCENARIO}|${item.WEEK_DATE}`;
        const existingQty = existingMap.get(key);
        const newQty = item.QUANTITY;

        if (!existingQty || parseFloat(existingQty) == parseFloat(newQty)) {
            continue;
        }
        else {
            weekArr.push(item.WEEK_DATE)
        }


    }


    return weekArr;
}


